class TelegramBatcher:
    """
    v9.1 FIX: Batch Telegram alerts to prevent 429 rate limits.
    Was: 5 rate limit errors per 784 days
    Fix: Queue non-critical alerts, batch every 30 seconds
    Only IMMEDIATE: SL hit, GTT trigger, token expiry, order placed
    """
    _queue = []
    _lock = threading.Lock()
    _last_flush = 0
    BATCH_INTERVAL = 30  # seconds
    IMMEDIATE_KEYWORDS = ['SL HIT', 'GTT', 'TOKEN', 'ORDER PLACED', 'EMERGENCY', 'KILL', 'OOM']
    
    @classmethod
    def add(cls, msg, priority='normal'):
        """Add message to queue. 'immediate' bypasses batching."""
        if priority == 'immediate' or any(kw in msg.upper() for kw in cls.IMMEDIATE_KEYWORDS):
            return msg  # Return for immediate sending
        with cls._lock:
            cls._queue.append({'msg': msg, 'time': time.time()})
        return None  # Queued, not sent immediately
    
    @classmethod
    def flush(cls):
        """Flush queued messages as single batched message."""
        with cls._lock:
            if not cls._queue:
                return None
            if time.time() - cls._last_flush < cls.BATCH_INTERVAL:
                return None
            msgs = cls._queue.copy()
            cls._queue.clear()
            cls._last_flush = time.time()
        
        if not msgs:
            return None
        
        batched = f"📋 *DIGEST ({len(msgs)} alerts)*\n"
        batched += "─" * 30 + "\n"
        for m in msgs[-20:]:  # Last 20 max
            batched += f"• {m['msg'][:100]}\n"
        if len(msgs) > 20:
            batched += f"... +{len(msgs)-20} more\n"
        return batched


class DVMFreshnessCheck:
    """
    v9.1 FIX: Prevent stale DVM scores (was 4 bugs in 784 days).
    Forces DVM refresh at 09:20 IST before market open.
    Rejects any DVM data older than 24 hours.
    """
    _cache = {}
    _cache_time = {}
    MAX_AGE_SECONDS = 86400  # 24 hours
    
    @classmethod
    def is_fresh(cls, symbol):
        """Check if DVM data for symbol is fresh enough."""
        if symbol not in cls._cache_time:
            return False
        age = time.time() - cls._cache_time[symbol]
        return age < cls.MAX_AGE_SECONDS
    
    @classmethod
    def update(cls, symbol, dvm_score):
        """Update DVM cache with fresh score."""
        cls._cache[symbol] = dvm_score
        cls._cache_time[symbol] = time.time()
    
    @classmethod
    def get(cls, symbol):
        """Get cached DVM score if fresh, else None."""
        if cls.is_fresh(symbol):
            return cls._cache.get(symbol)
        return None
    
    @classmethod
    def morning_refresh_needed(cls):
        """Check if morning refresh should run (09:15-09:25 IST)."""
        try:
            now = datetime.now(IST)
            if now.hour == 9 and 15 <= now.minute <= 25:
                return True
        except:
            pass
        return False
    
    @classmethod
    def clear_stale(cls):
        """Remove all stale entries."""
        stale = [s for s in cls._cache_time if not cls.is_fresh(s)]
        for s in stale:
            cls._cache.pop(s, None)
            cls._cache_time.pop(s, None)
        return len(stale)


class GTTPriceValidator:
    """
    v9.1 FIX: Validate GTT trigger prices before placement.
    Was: 4 'GTT Price OOR' errors — trigger >20% from LTP
    Fix: Pre-validate and recalculate if needed.
    """
    MAX_DEVIATION = 0.20  # 20% max from LTP
    
    @classmethod
    def validate_and_fix(cls, entry_price, sl_price, tp_price, atr):
        """
        Validate GTT prices. If OOR, recalculate to fit within Kite's range.
        Returns: (sl_price, tp_price, was_fixed: bool)
        """
        was_fixed = False
        
        # Check SL
        sl_deviation = abs(entry_price - sl_price) / entry_price
        if sl_deviation > cls.MAX_DEVIATION:
            # Clamp SL to max 20% below entry
            sl_price = round(entry_price * (1 - cls.MAX_DEVIATION), 2)
            was_fixed = True
            logger.warning(f"GTT FIX: SL clamped to {sl_price} (was >{cls.MAX_DEVIATION*100}% from entry)")
        
        # Check TP
        tp_deviation = abs(tp_price - entry_price) / entry_price
        if tp_deviation > cls.MAX_DEVIATION * 2:  # Allow wider for TP (40%)
            tp_price = round(entry_price * (1 + cls.MAX_DEVIATION * 2), 2)
            was_fixed = True
            logger.warning(f"GTT FIX: TP clamped to {tp_price} (was >{cls.MAX_DEVIATION*200}% from entry)")
        
        return sl_price, tp_price, was_fixed


class PartialFillHandler:
    """
    v9.1 FIX: Handle partial fills gracefully.
    Was: 5 partial fill errors — position size doesn't match GTT qty
    Fix: Check filled qty after order, adjust GTT accordingly.
    """
    
    @classmethod
    def check_and_handle(cls, kite, order_id, expected_qty, symbol):
        """
        After placing an order, check if fully filled.
        Returns: (actual_qty, action_taken)
        """
        try:
            orders = kite.orders()
            for o in orders:
                if str(o.get('order_id')) == str(order_id):
                    filled = o.get('filled_quantity', 0)
                    pending = o.get('pending_quantity', 0)
                    
                    if filled == expected_qty:
                        return filled, "FULL_FILL"
                    
                    if filled == 0:
                        return 0, "NO_FILL"
                    
                    fill_pct = filled / expected_qty
                    
                    if fill_pct >= 0.50:
                        # Keep partial position, cancel remaining
                        if pending > 0:
                            try:
                                kite.cancel_order(variety='regular', order_id=order_id)
                            except:
                                pass
                        logger.info(f"PARTIAL FILL [{symbol}]: {filled}/{expected_qty} ({fill_pct:.0%}) — keeping position, adjusting GTT")
                        return filled, "PARTIAL_KEEP"
                    else:
                        # Too small — cancel everything
                        try:
                            kite.cancel_order(variety='regular', order_id=order_id)
                        except:
                            pass
                        logger.info(f"PARTIAL FILL [{symbol}]: {filled}/{expected_qty} ({fill_pct:.0%}) — too small, cancelling")
                        return filled, "PARTIAL_CANCEL"
            
            return expected_qty, "ORDER_NOT_FOUND"
        except Exception as e:
            logger.error(f"PartialFillHandler error [{symbol}]: {e}")
            return expected_qty, "ERROR"


class SafeJSONWriter:
    """
    v9.1 FIX: Atomic JSON writes to prevent null byte corruption.
    Was: 4 null byte corruption events destroying holdings data
    Fix: Write to .tmp file first, then atomic rename. SHA256 checksum.
    """
    
    @staticmethod
    def write(filepath, data):
        """Atomic write with checksum verification."""
        tmp_path = filepath + '.tmp'
        try:
            json_str = json.dumps(data, indent=2, default=str)
            
            # Verify no null bytes
            if '\x00' in json_str or '\0' in json_str:
                logger.error(f"SafeJSON: Null bytes detected in data for {filepath} — aborting write")
                return False
            
            # Write to temp file
            with open(tmp_path, 'w') as f:
                f.write(json_str)
                f.flush()
                os.fsync(f.fileno())
            
            # Verify temp file is valid JSON
            with open(tmp_path, 'r') as f:
                json.loads(f.read())  # Will raise if corrupt
            
            # Atomic rename
            os.replace(tmp_path, filepath)
            
            # Write checksum
            checksum = hashlib.sha256(json_str.encode()).hexdigest()[:16]
            with open(filepath + '.sha', 'w') as f:
                f.write(checksum)
            
            return True
        except Exception as e:
            logger.error(f"SafeJSON write failed [{filepath}]: {e}")
            # Clean up temp file
            if os.path.exists(tmp_path):
                os.remove(tmp_path)
            return False
    
    @staticmethod
    def read(filepath):
        """Read JSON with corruption detection."""
        try:
            with open(filepath, 'r') as f:
                raw = f.read()
            
            # Check for null bytes
            if '\x00' in raw:
                logger.error(f"SafeJSON: Null bytes in {filepath} — attempting recovery")
                raw = raw.replace('\x00', '')
            
            return json.loads(raw)
        except json.JSONDecodeError as e:
            logger.error(f"SafeJSON: Corrupt JSON in {filepath}: {e}")
            # Try backup
            backup = filepath + '.bak'
            if os.path.exists(backup):
                logger.info(f"SafeJSON: Restoring from backup {backup}")
                with open(backup, 'r') as f:
                    return json.loads(f.read())
            return None


