class VolumeBreakoutConfirm:
    """
    v9.1 Phase 3: Require 2x average volume for breakout confirmation.
    Reduces false breakout bugs from ~8 to ~3.
    """
    VOLUME_MULTIPLIER = 2.0
    
    @classmethod
    def confirm(cls, current_volume, avg_volume):
        """Returns True if volume confirms breakout."""
        if avg_volume <= 0:
            return True  # No data, allow
        return current_volume >= avg_volume * cls.VOLUME_MULTIPLIER


class SentimentTieBreaker:
    """
    v9.1 Phase 3: When filing says BUY but news says SELL (or vice versa),
    use market regime as tie-breaker instead of deadlocking.
    Eliminates ~4 sentiment conflict bugs.
    """
    
    @classmethod
    def resolve(cls, filing_sentiment, news_sentiment, vix_regime):
        """
        Resolve conflicting signals using regime as tiebreaker.
        Returns: 'BUY', 'SELL', or 'HOLD'
        """
        if filing_sentiment == news_sentiment:
            return filing_sentiment
        
        # Conflict! Use regime
        if vix_regime in ('CONFIDENCE', 'EUPHORIA'):
            # Bull market — trust the bullish signal
            if 'BUY' in (filing_sentiment, news_sentiment):
                return 'BUY'
        elif vix_regime in ('EXTREME_FEAR', 'FEAR'):
            # Bear market — trust the bearish signal
            if 'SELL' in (filing_sentiment, news_sentiment):
                return 'SELL'
        
        return 'HOLD'  # Uncertain — stay out


