def _get_pod_for_sector(sector_text):
    """Map a stock's sector to its Griffin pod. Returns pod config dict."""
    if not sector_text:
        return GRIFFIN_POD_CONFIG["SERVICES"]
    sector_lower = sector_text.lower()
    for pod_name, config in GRIFFIN_POD_CONFIG.items():
        for s in config["sectors"]:
            if s.lower() in sector_lower:
                return config
    return GRIFFIN_POD_CONFIG["SERVICES"]  # Default catch-all

def get_pod_for_sector(symbol_or_sector):
    """Wrapper: accepts symbol or sector text, returns pod config."""
    if " " in str(symbol_or_sector) or str(symbol_or_sector).islower():
        return _get_pod_for_sector(symbol_or_sector)
    try:
        if hasattr(TrendlyneScorer, "_cache") and symbol_or_sector in TrendlyneScorer._cache:
            _sec = TrendlyneScorer._cache[symbol_or_sector].get("sector", "")
            if _sec:
                return _get_pod_for_sector(_sec)
    except Exception:
        pass
    return GRIFFIN_POD_CONFIG["SERVICES"]



# ═══════════════════════════════════════════════════════════════════════════════
#  v25.4.0: TWO-ENGINE CAPITAL ALLOCATOR
#  Equity 70% | Safe F&O 20% | Moonshot 10%
#  Hard capital walls between engines. Moonshot losses NEVER eat Equity.
# ═══════════════════════════════════════════════════════════════════════════════

TWO_ENGINE_TIERS = [
    # (max_capital, equity_pct, unified_fno_pct)  v25.5.0: merged Safe F&O + Moonshot
    (300_000,       0.75, 0.25),   # ₹1-3L   — conservative
    (500_000,       0.70, 0.30),   # ₹3-5L   — standard split
    (1_000_000,     0.65, 0.35),   # ₹5-10L  — more F&O firepower
    (2_500_000,     0.60, 0.40),   # ₹10-25L — balanced growth
    (float('inf'),  0.50, 0.50),   # ₹25L+   — aggressive multi-engine
]

def get_two_engine_split(total_capital):
    """Return (equity_pct, fno_pct) for given capital. v25.5.0: unified F&O engine."""
    for threshold, eq, fno in TWO_ENGINE_TIERS:
        if total_capital <= threshold:
            return eq, fno
    return 0.50, 0.50


class MoonshotScanner:
    """
    v25.4.0: Deep OTM high-beta lottery ticket scanner.
    
    Hunts for:
      - High-beta stocks (beta > 1.5) with upcoming catalysts
      - Deep OTM call options (delta 0.05-0.15) on these stocks
      - Weekly/monthly options expiring in 5-21 days
      - Small position size (max 2% of moonshot capital per ticket)
    
    Edge: When a high-beta stock moves 10%, a deep OTM option
    can return 500-2000%. Risk is capped at the premium paid.
    
    Criteria for a moonshot candidate:
      1. F&O-eligible stock (in NFO instruments list)
      2. Beta > 1.3 (high-beta, volatile)
      3. Upcoming catalyst within 21 days (earnings, RBI, filing)
      4. OTM strike at least 5% above current price (calls) or below (puts)
      5. Premium affordable within moonshot budget
      6. Max 3 active moonshot tickets at a time
    """

    MAX_ACTIVE_TICKETS = 3
    MAX_PCT_PER_TICKET = 0.30     # Max 30% of moonshot capital per ticket
    MIN_BETA = 1.3
    OTM_MIN_PCT = 0.05            # Strike at least 5% OTM
    OTM_MAX_PCT = 0.20            # Strike at most 20% OTM (not too far)
    EXPIRY_MIN_DAYS = 1           # v25.5.4-fix: allow entries 1 day before catalyst
    EXPIRY_MAX_DAYS = 21          # Max 21 days — theta kills longer holds
    SL_PCT = 0.50                 # Cut at 50% premium loss
    # Target: let winners run, no fixed target — ride the catalyst wave

    # v25.4.0: Scan ALL F&O stocks — not a hardcoded list
    # The principles (catalyst + high beta + affordable premium) apply to every F&O stock.
    # HIGH_BETA_WATCHLIST is now dynamically built from FNO_STOCKS + Kite instruments.
    HIGH_BETA_WATCHLIST = list(FNO_STOCKS)  # ALL 218+ F&O eligible stocks

    # Sectors that are naturally high-beta (get scoring bonus)
    HIGH_BETA_SECTORS = {"METALS", "INFRA", "ENERGY", "SERVICES", "BANKING"}
    MODERATE_BETA_SECTORS = {"IT", "AUTO", "CHEMICALS"}
    LOW_BETA_SECTORS = {"FMCG", "PHARMA"}  # Still scanned, just lower beta bonus

    def __init__(self, fno_intel=None, kite=None):
        self.fno_intel = fno_intel
        self.kite = kite
        self.active_tickets = []    # Current moonshot positions
        self.candidate_queue = []   # Ranked candidates waiting
        self._last_scan = None
        self._scan_results_cache = []

    def scan_candidates(self, kite=None, fno_intel=None, scans_data=None):
        """
        Scan for moonshot candidates. Returns ranked list.
        
        Pipeline:
          1. Filter HIGH_BETA_WATCHLIST for F&O eligibility
          2. Check for upcoming catalysts (earnings, filings, macro)
          3. Score each candidate (beta × catalyst_score × affordability)
          4. Rank by score descending
          5. Return top candidates that fit moonshot budget
        """
        _kite = kite or self.kite
        _intel = fno_intel or self.fno_intel
        if not _kite:
            logger.warning("MoonshotScanner: No Kite connection — skipping scan")
            return []

        candidates = []
        today = now_ist()  # v25.5.4-fix: use IST not UTC

        for symbol in self.HIGH_BETA_WATCHLIST:
            try:
                score = 0
                catalyst_type = None
                catalyst_date = None
                direction = "BULLISH"  # Default bullish, overridden by momentum/catalyst

                # ── Check Early Bird signals from FNOIntelEngine ──
                if _intel and hasattr(_intel, 'early_bird_signals'):
                    for sig in _intel.early_bird_signals:
                        if sig.get("symbol") == symbol:
                            score += sig.get("score", 0) * 0.5
                            catalyst_type = sig.get("type", "EARLY_BIRD")
                            break

                # ── Check earnings calendar ──
                if _intel and hasattr(_intel, 'earnings_calendar'):
                    for ec in _intel.earnings_calendar:
                        if ec.get("symbol") == symbol:
                            days_to_result = (ec.get("date", today) - today).days
                            if self.EXPIRY_MIN_DAYS <= days_to_result <= self.EXPIRY_MAX_DAYS:
                                score += 40  # Earnings play
                                catalyst_type = "EARNINGS"
                                catalyst_date = ec.get("date")
                                break

                # ── Check RBI MPC / US Fed dates ──
                # v25.5.4: RBI rate decisions affect ALL sectors, not just banks
                # Banks +30, Rate-sensitive (auto, real estate, NBFC) +25, All others +15
                _RATE_SENSITIVE = {"SBIN","HDFCBANK","ICICIBANK","KOTAKBANK","AXISBANK",
                    "PNB","CANBK","FEDERALBNK","IDFCFIRSTB","BANDHANBNK","INDUSINDBK",
                    "LICHSGFIN","BAJFINANCE","MUTHOOTFIN","MANAPPURAM","CHOLAFIN",
                    "SBICARD","TATAMOTORS","MARUTI","M&M","HEROMOTOCO","BAJAJ-AUTO",
                    "DLF","GODREJPROP","OBEROIRLTY","PRESTIGE","BRIGADE",
                    "LT","ULTRACEMCO","ACC","AMBUJACEM","SHREECEM"}
                for mpc_date_str in FNOIntelEngine.RBI_MPC_DATES_2026:
                    mpc_date = datetime.strptime(mpc_date_str, "%Y-%m-%d")
                    days_to = (mpc_date - today).days
                    if self.EXPIRY_MIN_DAYS <= days_to <= self.EXPIRY_MAX_DAYS:
                        if symbol in _RATE_SENSITIVE:
                            score += 30  # Direct rate impact
                            catalyst_type = "RBI_MPC"
                            catalyst_date = mpc_date
                        else:
                            score += 15  # All stocks move on rate decisions
                            if not catalyst_type:
                                catalyst_type = "RBI_MPC_BROAD"
                                catalyst_date = mpc_date
                        break

                # ── Check high-impact filing signals ──
                if _intel and hasattr(_intel, 'filing_queue'):
                    for fq in _intel.filing_queue:
                        if fq.get("symbol") == symbol and fq.get("score", 0) >= 70:
                            score += fq.get("score", 0) * 0.4
                            catalyst_type = fq.get("type", "FILING")
                            break

                # ── Live momentum check: stocks with big moves TODAY ──
                # This catches UPL-type moves where cheap OTM becomes valuable
                # v25.5.5: Use scan data for momentum (ltp doesn't have change%)
                try:
                    _moon_chg = 0
                    if scans_data and symbol in scans_data:
                        _moon_chg = scans_data[symbol].get("day_change_pct", 0)
                    elif _kite:
                        # Fallback: use quote() which has OHLC for change calc
                        _mq = _kite.quote([f"NSE:{symbol}"])
                        _mqd = list(_mq.values())[0] if _mq else {}
                        _m_ltp = _mqd.get("last_price", 0)
                        _m_close = _mqd.get("ohlc", {}).get("close", 0)
                        if _m_close > 0 and _m_ltp > 0:
                            _moon_chg = ((_m_ltp - _m_close) / _m_close) * 100
                    if abs(_moon_chg) >= 3.0:
                        score += 25  # Big mover today — options will be volatile
                        if not catalyst_type: catalyst_type = f"BIG_MOVE_{_moon_chg:+.1f}%"
                        if _moon_chg < -3.0: direction = "BEARISH"
                    elif abs(_moon_chg) >= 1.5:
                        score += 10  # Moderate mover
                except Exception:
                    pass

                # ── Beta bonus: sector-based scoring for ALL F&O stocks ──
                pod = get_pod_for_sector(symbol)
                pod_name = [k for k, v in GRIFFIN_POD_CONFIG.items() if v == pod][0]
                if pod_name in self.HIGH_BETA_SECTORS:
                    score += 15  # High-beta sectors (metals, infra, energy, banks)
                elif pod_name in self.MODERATE_BETA_SECTORS:
                    score += 10  # Moderate beta (IT, auto, chemicals)
                elif pod_name in self.LOW_BETA_SECTORS:
                    score += 5   # Low beta (FMCG, pharma) — still valid with strong catalyst
                else:
                    score += 8   # Default for unclassified

                if score >= 18:  # v25.5.4: Lowered from 25 — let more moonshots through, exit logic manages risk
                    candidates.append({
                        "symbol": symbol,
                        "score": round(score, 1),
                        "catalyst_type": catalyst_type or "TECHNICAL",
                        "catalyst_date": catalyst_date,
                        "direction": direction,
                        "pod": pod_name,
                    })

            except Exception as e:
                logger.debug(f"MoonshotScanner [{symbol}]: {e}")
                continue

        # Sort by score descending
        candidates.sort(key=lambda x: x["score"], reverse=True)
        self._scan_results_cache = candidates[:10]  # Keep top 10
        self._last_scan = now_ist()  # v25.6.0-fix: IST
        
        # v25.4.0: Prefer far-month expiry (June+) for better liquidity
        for c in candidates:
            c["preferred_expiry"] = "SMART"  # Bot picks best expiry per catalyst timing
            c["exit_rule"] = "DTE ≤ 12 emergency | DTE ≤ 15 need +100% | ≤ 18 cut losers | ≤ 20 warn"

        if candidates:
            logger.info(
                f"🚀 MOONSHOT SCAN: {len(candidates)} candidates from {len(self.HIGH_BETA_WATCHLIST)} F&O stocks, "
                f"top 3: {', '.join(f'{c["symbol"]}({c["score"]})' for c in candidates[:3])}"
            )
        else:
            logger.info("🚀 MOONSHOT SCAN: 0 candidates found from full F&O universe")
        return candidates[:10]

    def scan_cheap_options(self, kite, fno_intel=None, scans_data=None):
        """
        v25.6.0: SMART CHEAP OPTIONS SCANNER — deep option chain analysis.
        
        NOT just any cheap option — analyzes:
        1. CATALYST STRENGTH: What's driving the move? (earnings > RBI > filing > momentum)
        2. OPTION CHAIN HEALTH: OI buildup, bid-ask spread, volume
        3. PREMIUM SWEET SPOT: ₹2-₹50 range (not ₹0.05 illiquid garbage)
        4. DIRECTION CONFIDENCE: Stock momentum + sector + macro alignment
        5. RISK/REWARD: Max loss = premium paid, target = 3-10x
        
        A ₹2 option with:
        - High OI buildup = smart money positioning = GOOD
        - Zero OI, wide spread = no one wants it = SKIP
        - Catalyst in 2-5 days = perfect timing
        - Stock already moved 3%+ in direction = momentum confirmation
        """
        if not kite:
            return []
        
        candidates = []
        _today = now_ist()
        
        # ── Step 1: Build catalyst universe ──
        _catalyst_stocks = {}  # symbol → {type, days, direction, strength}
        
        # Earnings — STRONGEST catalyst for options
        if fno_intel and hasattr(fno_intel, 'earnings_calendar'):
            for ec in (fno_intel.earnings_calendar or []):
                _sym = ec.get("symbol", "")
                try:
                    _days = (ec.get("date", _today) - _today).days if hasattr(ec.get("date"), "days") else (ec.get("date") - _today).days
                except: _days = 999
                if 1 <= _days <= 10 and _sym in FNO_STOCKS:
                    _catalyst_stocks[_sym] = {"type": "EARNINGS", "days": _days, 
                        "direction": None, "strength": 95}  # Direction unknown pre-results
        
        # News/early bird signals
        if fno_intel and hasattr(fno_intel, 'early_bird_signals'):
            for sig in (fno_intel.early_bird_signals or []):
                _sym = sig.get("symbol", "")
                if _sym in FNO_STOCKS and _sym not in _catalyst_stocks:
                    _catalyst_stocks[_sym] = {"type": sig.get("type", "NEWS"), "days": 3,
                        "direction": sig.get("direction"), "strength": 70}
        
        # Recent filings — PROMOTER, BUYBACK, ORDER_WIN
        if fno_intel and hasattr(fno_intel, 'filing_queue'):
            for fq in (fno_intel.filing_queue or []):
                _sym = fq.get("symbol", "")
                if _sym in FNO_STOCKS and fq.get("score", 0) >= 40:
                    if _sym not in _catalyst_stocks or _catalyst_stocks[_sym]["strength"] < fq.get("score", 0):
                        _ftype = fq.get("type", "FILING")
                        _dir = "BULLISH" if _ftype in ("BUYBACK","PROMOTER","ORDER_WIN","SAST") else None
                        _catalyst_stocks[_sym] = {"type": _ftype, "days": 2,
                            "direction": _dir, "strength": fq.get("score", 60)}
        
        # Big movers today — momentum confirmation
        if scans_data:
            _sd_iter = scans_data.items() if isinstance(scans_data, dict) else ((d.get("symbol",""), d) for d in scans_data if isinstance(d, dict))
            for _sym, _data in _sd_iter:
                if _sym in FNO_STOCKS and isinstance(_data, dict):
                    _chg = abs(_data.get("day_change_pct", 0))
                    _vol = _data.get("volume_ratio", 0)
                    if _chg >= 2.0 and _vol >= 1.2:  # 2%+ move with volume
                        _dir = "BEARISH" if _data.get("day_change_pct", 0) < 0 else "BULLISH"
                        if _sym in _catalyst_stocks:
                            _catalyst_stocks[_sym]["direction"] = _dir
                            _catalyst_stocks[_sym]["strength"] += 20  # Momentum confirmation
                        else:
                            _catalyst_stocks[_sym] = {"type": f"MOMENTUM_{_chg:.0f}%", "days": 1,
                                "direction": _dir, "strength": 60 + min(_chg * 5, 30)}
        
        # RBI MPC — rate-sensitive stocks
        _rbi_dates = ["2026-04-09", "2026-06-06", "2026-08-08", "2026-10-03", "2026-12-05"]
        for _rd in _rbi_dates:
            try:
                _rbi_d = datetime.strptime(_rd, "%Y-%m-%d").date()
                _rbi_diff = (_rbi_d - _today.date()).days
                if 1 <= _rbi_diff <= 5:
                    _rate_stocks = ["SBIN","HDFCBANK","ICICIBANK","KOTAKBANK","AXISBANK",
                        "PNB","CANBK","FEDERALBNK","IDFCFIRSTB","BANDHANBNK",
                        "BAJFINANCE","LICHSGFIN","MANAPPURAM","DLF","GODREJPROP",
                        "TATAMOTORS","MARUTI","M&M","LT","ULTRACEMCO"]
                    for _rs in _rate_stocks:
                        if _rs not in _catalyst_stocks or _catalyst_stocks[_rs]["strength"] < 80:
                            _catalyst_stocks[_rs] = {"type": "RBI_MPC", "days": _rbi_diff,
                                "direction": "BULLISH", "strength": 80}  # Rate cut expectation
            except: pass
        
        if not _catalyst_stocks:
            logger.info("🔍 CHEAP OPTIONS: No catalyst stocks found")
            return []
        
        logger.info(f"🔍 CHEAP OPTIONS: {len(_catalyst_stocks)} catalyst stocks — analyzing option chains")
        
        # ── Step 2: Cache NFO instruments + lot sizes ──
        _nfo_lot_cache = {}
        _nfo_instruments = []
        try:
            _nfo_instruments = kite.instruments("NFO")
            for _ni in _nfo_instruments:
                _ni_name = _ni.get("name", "")
                if _ni_name and _ni_name not in _nfo_lot_cache:
                    _nfo_lot_cache[_ni_name] = _ni.get("lot_size", 1)
        except Exception:
            pass
        
        # ── Step 3: Batch LTP for spot prices ──
        _sym_list = [f"NSE:{s}" for s in list(_catalyst_stocks.keys())[:30]]
        _batch_ltp = {}
        try:
            if _sym_list:
                _batch_ltp = kite.ltp(_sym_list)
        except Exception:
            pass
        
        # ── Step 4: Deep analysis per catalyst stock ──
        for _sym, _cat_info in list(_catalyst_stocks.items())[:25]:
            try:
                _spot = _batch_ltp.get(f"NSE:{_sym}", {}).get("last_price", 0)
                if _spot <= 0: continue
                
                _lot = _nfo_lot_cache.get(_sym, 1)
                _direction = _cat_info.get("direction", "BULLISH")
                if not _direction: _direction = "BULLISH"  # Default
                
                # Pick OTM strike — 3-8% OTM for cheap premium
                _step = 50 if _spot > 1000 else (10 if _spot > 200 else (5 if _spot > 50 else 1))
                _otm_pct = 0.05  # 5% OTM default
                if _cat_info["strength"] >= 85:
                    _otm_pct = 0.03  # Strong catalyst = closer strike
                elif _cat_info["strength"] < 60:
                    _otm_pct = 0.08  # Weak signal = deeper OTM (cheaper)
                
                if "BULL" in _direction:
                    _strike = round((_spot * (1 + _otm_pct)) / _step) * _step
                    _opt_type = "CE"
                else:
                    _strike = round((_spot * (1 - _otm_pct)) / _step) * _step
                    _opt_type = "PE"
                
                # ── Step 5: Find exact instrument and get LIVE quote ──
                _tradingsymbol = None
                _expiry_date = None
                for _inst in _nfo_instruments:
                    if (_inst["name"] == _sym and 
                        int(_inst["strike"]) == int(_strike) and
                        _inst["instrument_type"] == _opt_type):
                        _tradingsymbol = _inst["tradingsymbol"]
                        _expiry_date = _inst["expiry"]
                        break
                
                if not _tradingsymbol:
                    continue  # No matching instrument
                
                # Get LIVE option data — premium, OI, volume, bid-ask
                _option_data = {}
                try:
                    _q = kite.quote([f"NFO:{_tradingsymbol}"])
                    _option_data = list(_q.values())[0] if _q else {}
                except: continue
                
                _live_premium = _option_data.get("last_price", 0)
                _oi = _option_data.get("oi", 0)
                _volume = _option_data.get("volume", 0)
                _bid = _option_data.get("depth", {}).get("buy", [{}])[0].get("price", 0)
                _ask = _option_data.get("depth", {}).get("sell", [{}])[0].get("price", 0)
                _bid_qty = _option_data.get("depth", {}).get("buy", [{}])[0].get("quantity", 0)
                
                # ── Step 6: QUALITY FILTERS — skip garbage options ──
                _skip_reason = None
                
                # Filter 1: Premium must be ₹0.5-₹50 (sweet spot)
                if _live_premium < 0.5:
                    _skip_reason = f"premium ₹{_live_premium} too low (illiquid)"
                elif _live_premium > 50:
                    _skip_reason = f"premium ₹{_live_premium} too expensive"
                
                # Filter 2: Must have some OI (smart money present)
                if not _skip_reason and _oi < 1000:
                    _skip_reason = f"OI={_oi} too low (no smart money)"
                
                # Filter 3: Bid-ask spread must be reasonable (<50% of premium)
                if not _skip_reason and _bid > 0 and _ask > 0:
                    _spread_pct = (_ask - _bid) / _bid * 100 if _bid > 0 else 100
                    if _spread_pct > 50:
                        _skip_reason = f"spread {_spread_pct:.0f}% too wide"
                
                # Filter 4: Must have buyers (bid quantity)
                if not _skip_reason and _bid_qty < _lot:
                    _skip_reason = f"bid_qty={_bid_qty} < lot={_lot} (no exit liquidity)"
                
                # Filter 5: Cost must fit budget
                _cost = _live_premium * _lot
                if not _skip_reason and _cost > 15000:
                    _skip_reason = f"cost ₹{_cost:,.0f} > budget"
                
                if _skip_reason:
                    logger.debug(f"CHEAP OPTIONS [{_sym}]: SKIP — {_skip_reason}")
                    continue
                
                # ── Step 7: SCORE the option (higher = better trade) ──
                _score = _cat_info["strength"]  # Base: catalyst strength
                
                # OI buildup bonus (smart money confirmation)
                if _oi > 50000: _score += 15
                elif _oi > 10000: _score += 10
                elif _oi > 5000: _score += 5
                
                # Volume bonus (active trading)
                if _volume > 10000: _score += 10
                elif _volume > 1000: _score += 5
                
                # Tight spread bonus (liquid option)
                if _bid > 0 and _ask > 0:
                    _spread = (_ask - _bid) / _bid * 100 if _bid > 0 else 100
                    if _spread < 10: _score += 10  # Very liquid
                    elif _spread < 25: _score += 5
                
                # Cheap premium bonus (higher leverage)
                if _live_premium <= 5: _score += 15  # Ultra cheap = max leverage
                elif _live_premium <= 15: _score += 10
                elif _live_premium <= 30: _score += 5
                
                # Catalyst timing bonus
                _cat_days = _cat_info["days"]
                if 2 <= _cat_days <= 5: _score += 10  # Perfect timing
                elif _cat_days == 1: _score += 5  # Tight but ok
                
                _score = min(_score, 100)
                
                # ── Step 8: Calculate targets ──
                # Cheap options: SL = 50% of premium, T1 = 3x, T2 = 5x
                _sl = round(_live_premium * 0.50, 2)
                _t1 = round(_live_premium * 3.0, 2)
                _t2 = round(_live_premium * 5.0, 2)
                
                candidates.append({
                    "symbol": _sym,
                    "engine": "SMART_CHEAP_OPTIONS",
                    "score": _score,
                    "catalyst": f"{_cat_info['type']} in {_cat_days}d (str={_cat_info['strength']})",
                    "direction": _direction,
                    "data": {"price": _spot, "premium": _live_premium, "oi": _oi, 
                             "volume": _volume, "spread_pct": round((_ask-_bid)/_bid*100,1) if _bid > 0 else 0,
                             "strike": _strike, "opt_type": _opt_type, "lot": _lot,
                             "cost": round(_cost, 0), "tradingsymbol": _tradingsymbol},
                    "pod": "CATALYST",
                    "sl": _sl, "t1": _t1, "t2": _t2,
                })
                
                logger.info(
                    f"💎 SMART OPTION: {_sym} {_strike}{_opt_type} ₹{_live_premium} x{_lot}=₹{_cost:,.0f} | "
                    f"OI={_oi:,} Vol={_volume:,} | {_cat_info['type']} in {_cat_days}d | score={_score}"
                )
                
            except Exception as _e:
                logger.debug(f"Smart options [{_sym}]: {_e}")
                continue
        
        candidates.sort(key=lambda x: x["score"], reverse=True)
        if candidates:
            logger.info(f"🎯 SMART CHEAP OPTIONS: {len(candidates)} qualified — top: {str([c['symbol'] for c in candidates[:5]])}")
        else:
            logger.info("🔍 SMART CHEAP OPTIONS: 0 passed quality filters")
        return candidates[:10]

    def select_strike(self, symbol, ltp, direction="BULLISH"):
        """
        Select optimal OTM strike for moonshot.
        Returns (strike_price, option_type, estimated_premium).
        
        Logic: Pick strike that is 8-12% OTM — sweet spot between
        affordability and probability of profit.
        """
        if direction == "BULLISH":
            option_type = "CE"
            target_otm = 0.10  # 10% OTM
            strike = round(ltp * (1 + target_otm) / 50) * 50  # Round to nearest 50
            # Estimate premium: very rough — deep OTM typically 0.5-2% of strike
            est_premium = round(ltp * 0.01, 2)  # ~1% of LTP
        else:
            option_type = "PE"
            target_otm = 0.10
            strike = round(ltp * (1 - target_otm) / 50) * 50
            est_premium = round(ltp * 0.01, 2)

        return strike, option_type, est_premium

    def get_optimal_expiry(self, catalyst_days=None, premium_budget=None):
        """
        v25.4.0: SMART expiry selection — evaluate ALL available expiries.
        
        Picks the BEST expiry based on:
          - Catalyst timing: if catalyst is in 5 days, this month is fine
          - Premium cost: far months cost more, current month is cheaper
          - Exit safety: must have at least 12 days AFTER catalyst to exit safely
          - Liquidity: current month has best liquidity near ATM
        
        DECISION MATRIX:
          Catalyst in 1-7 days   → Current month IF DTE > 15, else next month
          Catalyst in 8-21 days  → Next month (safe buffer)
          Catalyst in 22-45 days → Month+2 (June type — long thesis)
          No specific catalyst   → Next month (balanced cost vs time)
          Moonshot (long shot)   → Month+2 (needs maximum time)
        
        Returns list of (year, month, score, reason) ranked best to worst.
        """
        today = now_ist()  # v25.5.4-fix: use IST not UTC
        options = []
        
        for offset in range(0, 3):  # Current, next, month+2
            m = today.month + offset
            y = today.year
            if m > 12:
                m -= 12
                y += 1
            
            # Estimate DTE (last Thursday of that month)
            import calendar
            last_day = calendar.monthrange(y, m)[1]
            # Find last Thursday
            from datetime import date
            exp_date = date(y, m, last_day)
            while exp_date.weekday() != 3:  # Thursday
                exp_date = exp_date - timedelta(days=1)
            
            dte = (exp_date - today.date()).days
            if dte < 5:
                continue  # Too close, skip
            
            score = 0
            reason = ""
            
            # ── Score based on catalyst timing ──
            if catalyst_days is not None:
                buffer_after_catalyst = dte - catalyst_days
                
                if buffer_after_catalyst >= 12:
                    # Enough time to exit safely after catalyst
                    score += 30
                    reason = f"DTE={dte}, {buffer_after_catalyst}d exit buffer after catalyst"
                elif buffer_after_catalyst >= 5:
                    score += 15
                    reason = f"DTE={dte}, tight {buffer_after_catalyst}d buffer"
                else:
                    score -= 20  # NOT ENOUGH EXIT TIME
                    reason = f"DTE={dte}, DANGER only {buffer_after_catalyst}d after catalyst"
            
            # ── Score based on DTE sweet spots ──
            if 20 <= dte <= 35:
                score += 20  # Sweet spot — good theta, good liquidity
                reason += " | sweet spot DTE"
            elif 35 < dte <= 60:
                score += 15  # More time but higher premium
                reason += " | far month, more time"
            elif 60 < dte <= 90:
                score += 10  # Long-dated, expensive
                reason += " | long-dated"
            elif dte < 20:
                score += 5   # Short but can work for quick catalyst
                reason += " | short-dated, quick play"
            
            # ── Liquidity bonus for current month ──
            if offset == 0:
                score += 5   # Current month = best liquidity
            
            # ── Premium cost (far months cost more) ──
            if offset == 0:
                score += 8   # Cheapest premium
            elif offset == 1:
                score += 4   # Moderate premium
            # month+2 = most expensive, no bonus
            
            options.append((y, m, dte, score, reason.strip(" |")))
        
        # Sort by score descending
        options.sort(key=lambda x: x[3], reverse=True)
        
        if options:
            best = options[0]
            logger.info(
                f"📅 Expiry selection: {best[0]}-{best[1]:02d} (DTE={best[2]}, "
                f"score={best[3]}) — {best[4]}"
            )
        
        return options

    def score_by_principles(self, symbol, ltp, pod_name, catalysts, dte):
        """
        v25.4.0: Universal F&O scoring principles applied to ANY stock.
        
        PRINCIPLES:
          1. HIGH BETA → bigger moves on catalyst → higher score
          2. UPCOMING CATALYST within 30 days → time-limited opportunity
          3. AFFORDABLE PREMIUM → deep OTM but not worthless
          4. FAR MONTH EXPIRY → minimum 40 DTE for safe exit window
          5. SECTOR MOMENTUM → sector rotating into favor
          6. VIX LEVEL → high VIX = expensive but big moves expected
        
        Returns score 0-100.
        """
        score = 0
        
        # Principle 1: Sector beta bonus
        if pod_name in self.HIGH_BETA_SECTORS:
            score += 20
        elif pod_name in self.MODERATE_BETA_SECTORS:
            score += 12
        elif pod_name in self.LOW_BETA_SECTORS:
            score += 6
        
        # Principle 2: Catalyst proximity
        if catalysts:
            nearest_days = min(c.get("days_to", 999) for c in catalysts) if catalysts else 999
            if nearest_days <= 7:
                score += 25    # Catalyst THIS WEEK — highest urgency
            elif nearest_days <= 14:
                score += 20    # Catalyst in 2 weeks
            elif nearest_days <= 30:
                score += 12    # Catalyst in a month
        
        # Principle 3: Affordability (LTP determines premium range)
        if ltp and ltp > 0:
            if ltp < 200:
                score += 8     # Cheap stock = cheap premium
            elif ltp < 500:
                score += 10    # Sweet spot
            elif ltp < 2000:
                score += 6     # Moderate premium
            else:
                score += 3     # Expensive — big lot sizes eat capital
        
        # Principle 4: DTE check
        if 40 <= dte <= 75:
            score += 10        # Perfect DTE range for moonshot
        elif 30 <= dte < 40:
            score += 5         # Acceptable but tight
        elif dte < 30:
            score -= 10        # Too close — skip (will be filtered by exit engine)
        
        # Principle 5: Earnings play bonus
        for c in (catalysts or []):
            if c.get("type") in ("EARNINGS", "QUARTERLY_RESULTS"):
                score += 15    # Earnings are the #1 catalyst for options
                break
            if c.get("type") in ("RBI_MPC", "US_FED"):
                score += 10    # Macro event — banks and rate-sensitives
                break
            if c.get("type") in ("BUYBACK", "MERGER_ACQUISITION", "DEMERGER"):
                score += 20    # Corporate action — massive moves
                break
        
        return min(score, 100)

    def can_take_ticket(self):
        """Check if we can add another moonshot position."""
        active = len([t for t in self.active_tickets if t.get("status") == "ACTIVE"])
        return active < self.MAX_ACTIVE_TICKETS

    def get_ticket_size(self, moonshot_capital, est_premium, lot_size):
        """Calculate number of lots based on moonshot capital and risk limits."""
        cost_per_lot = est_premium * lot_size
        if cost_per_lot <= 0:
            return 0
        max_spend = moonshot_capital * self.MAX_PCT_PER_TICKET
        lots = int(max_spend / cost_per_lot)
        return max(lots, 0)  # At least 0 (won't trade if can't afford 1 lot)

    def to_dict(self):
        return {
            "active_tickets": self.active_tickets,
            "candidate_queue": self._scan_results_cache,
            "last_scan": self._last_scan.isoformat() if self._last_scan else None,
        }



# ═══════════════════════════════════════════════════════════════════════════════
#  v25.4.0: F&O + MOONSHOT EXIT ENGINE
#  Aggressive time-based + profit-based exits for ALL option positions.
#  Deep OTM theta decay is brutal — exit EARLY, not at expiry.
# ═══════════════════════════════════════════════════════════════════════════════

class FNOExitEngine:
    """
    Comprehensive exit logic for Safe F&O AND Moonshot positions.
    DESIGNED FROM REAL NSE EXPERIENCE: Liquidity dies 7-10 days before expiry.
    
    EXIT RULES (applied every 5 minutes during market hours):
    
    ═══ MONTHLY OPTIONS — TIME-BASED EXITS ═══
    1. DTE <= 7:   EMERGENCY EXIT at market. Liquidity DEAD beyond this point.
    2. DTE <= 10:  EXIT unless sitting on +100% profit. Last chance for clean exit.
    3. DTE <= 12:  EXIT all losers. No time to recover AND no buyers coming.
    4. DTE <= 15:  WARNING — if P&L < -20%, exit now. Theta accelerating.
    5. 50% RULE:   If 50% of your holding time is gone and P&L < +30%, EXIT.
                   (Bought at DTE=21 → must exit by DTE=11 unless profitable)
    
    ═══ WEEKLY OPTIONS — TIME-BASED EXITS ═══
    6. Day before expiry (DTE=1): EMERGENCY EXIT at 9:30 AM. No exceptions.
    7. 2 days before expiry (DTE=2): EXIT unless +50% profit.
    8. Max hold = 2 trading days. Buy Monday → exit Wednesday morning.
    9. Catalyst protection: Hold through catalyst day, exit catalyst+1 morning.
    
    ═══ PROFIT-BASED EXITS ═══
    10. Premium 3x (+200%): Book 50%, trail rest with 25% trailing SL
    11. Premium 5x (+400%): Book 100% — full exit, take the gift
    12. Premium 10x (+900%): Book 100% — never give back a 10-bagger
    
    ═══ LOSS-BASED EXITS ═══
    13. Premium drops 50%: HARD SL — exit immediately (all positions)
    14. Premium drops 30% AND DTE < 15: EXIT — theta + loss = death
    15. Premium drops 20% AND catalyst passed: EXIT — thesis broken
    
    ═══ MOONSHOT-SPECIFIC ═══
    16. Catalyst passed without move: EXIT next morning (thesis expired)
    17. Stock moves AGAINST direction > 3%: EXIT — wrong bet
    18. 50% of time gone + flat: EXIT — opportunity cost
    """

    # ── MONTHLY TIME THRESHOLDS (NSE liquidity reality) ──
    EMERGENCY_DTE = 12         # v25.4.0: EXIT 12 days before expiry — NSE liquidity dies early
    CRITICAL_DTE = 15          # Last clean exit window — must have +100% to hold
    LOSER_CUT_DTE = 18         # Cut all losers early — no recovery with dying liquidity
    WARNING_DTE = 20           # Cut if losing > 20% — theta visible by now
    HALF_TIME_RULE = 0.50      # Exit at 50% of holding period if not profitable

    # ── WEEKLY TIME THRESHOLDS ──
    WEEKLY_EMERGENCY_DTE = 1   # Day before expiry = emergency
    WEEKLY_CRITICAL_DTE = 2    # 2 days before = exit unless profit
    WEEKLY_MAX_HOLD_DAYS = 2   # Max 2 trading days hold

    # ── PROFIT TARGETS (as multiplier of entry premium) ──
    PARTIAL_BOOK_3X = 999.0      # GIR: DISABLED — trailing SL handles upside
    FULL_EXIT_5X = 999.0          # GIR: DISABLED — trailing SL handles upside
    FULL_EXIT_10X = 999.0         # GIR: DISABLED — trailing SL handles upside

    # ── LOSS THRESHOLDS ──
    HARD_SL_PCT = 0.50         # 50% premium loss = hard stop
    THETA_SL_PCT = 0.30        # 30% loss with DTE < 15 = exit
    THESIS_SL_PCT = 0.20       # 20% loss + catalyst passed = exit

    # ── TRAILING STOP (activated after 100%+ profit) ──
    TRAIL_ACTIVATION = 0.20       # GIR: Trail starts after +20% (was 100%)
    TRAIL_PCT = 0.15              # GIR: 15% trailing from peak (was 25%)

    def __init__(self):
        self.exit_log = []
        self._peak_premiums = {}   # Track highest premium per position

    def check_exits(self, positions, spot_prices, dte_func, expiry_func):
        """
        Check all F&O + Moonshot positions for exit signals.
        
        Args:
            positions: dict of {key: position_dict}
            spot_prices: dict of {symbol: current_spot_price}
            dte_func: callable returning days to expiry
            expiry_func: callable returning expiry date
        
        Returns:
            list of (key, reason, urgency) tuples for positions to exit.
            urgency: "EMERGENCY" | "URGENT" | "NORMAL"
        """
        exits = []
        dte = dte_func() if callable(dte_func) else dte_func

        for key, pos in positions.items():
            symbol = pos.get("symbol", "")
            entry_premium = pos.get("premium", 0)
            current_premium = pos.get("current_premium", entry_premium)
            cost = pos.get("cost", 0)
            engine = pos.get("engine", "SAFE_FNO")  # SAFE_FNO or MOONSHOT
            catalyst_date = pos.get("catalyst_date")
            direction = pos.get("direction", "BULLISH")

            if entry_premium <= 0:
                continue

            pnl_pct = ((current_premium - entry_premium) / entry_premium) * 100
            pnl_mult = current_premium / entry_premium  # 2.0 = doubled

            # Track peak premium for trailing stop
            peak = self._peak_premiums.get(key, entry_premium)
            if current_premium > peak:
                self._peak_premiums[key] = current_premium
                peak = current_premium

            # ═══ TIME-BASED EXITS (NSE liquidity-aware) ═══
            
            # Determine if weekly or monthly option
            _entry_dte = pos.get("entry_dte", 30)  # DTE when position was opened
            _is_weekly = _entry_dte <= 7
            _days_held = _entry_dte - dte
            _half_time_dte = _entry_dte * self.HALF_TIME_RULE

            if _is_weekly:
                # ── WEEKLY OPTION RULES ──
                
                # Rule 6: Day before expiry — EMERGENCY
                if dte <= self.WEEKLY_EMERGENCY_DTE:
                    exits.append((key, f"🚨 WEEKLY EMERGENCY: DTE={dte}, NO BUYERS TOMORROW — exiting NOW", "EMERGENCY"))
                    continue
                
                # Rule 7: 2 days before — exit unless profitable
                if dte <= self.WEEKLY_CRITICAL_DTE and pnl_mult < 1.5:
                    exits.append((key, f"⏰ Weekly DTE={dte}, need +50% to hold, have {pnl_pct:.0f}%", "URGENT"))
                    continue
                
                # Rule 8: Max 2 days hold
                if _days_held >= self.WEEKLY_MAX_HOLD_DAYS and pnl_pct < 30:
                    exits.append((key, f"⏰ Weekly max hold {_days_held}d, P&L only {pnl_pct:.0f}% — exiting", "URGENT"))
                    continue
                
                # Rule 9: Catalyst protection — if catalyst is today or tomorrow, HOLD
                if catalyst_date:
                    try:
                        _cat = catalyst_date if isinstance(catalyst_date, type(datetime.now().date())) else datetime.strptime(str(catalyst_date)[:10], "%Y-%m-%d").date()
                        _today = now_ist().date()  # v25.5.5: IST
                        if _cat >= _today and (_cat - _today).days <= 1:
                            logger.info(f"🛡️ Catalyst protection: {symbol} catalyst in {(_cat - _today).days}d — HOLDING")
                            continue  # Skip all time exits — catalyst imminent
                    except Exception:
                        pass

            else:
                # ── MONTHLY OPTION RULES (NSE liquidity reality) ──
                
                # Rule 1: DTE <= 7 — LIQUIDITY IS DEAD
                if dte <= self.EMERGENCY_DTE:
                    exits.append((key, f"🚨 MONTHLY EMERGENCY: DTE={dte}, 12 DAYS TO EXPIRY — LIQUIDITY DEAD — no buyers exist", "EMERGENCY"))
                    continue
                
                # Rule 2: DTE <= 10 — last clean exit window
                if dte <= self.CRITICAL_DTE and pnl_mult < 2.0:
                    exits.append((key, f"⏰ Last exit window DTE={dte}, need +100% to hold, have {pnl_pct:.0f}%", "URGENT"))
                    continue
                
                # Rule 3: DTE <= 12 — cut all losers
                if dte <= self.LOSER_CUT_DTE and pnl_pct < 0:
                    exits.append((key, f"📉 DTE={dte} loser cut: P&L={pnl_pct:.0f}% — no recovery time with liquidity", "URGENT"))
                    continue
                
                # Rule 4: DTE <= 15 — cut if losing > 20%
                if dte <= self.WARNING_DTE and pnl_pct < -20:
                    exits.append((key, f"📉 DTE={dte} warning: losing {pnl_pct:.0f}% — theta accelerating", "NORMAL"))
                    continue
                
                # Rule 5: 50% RULE — half your time is gone, not profitable = EXIT
                if dte <= _half_time_dte and pnl_pct < 30:
                    exits.append((key, 
                        f"⏰ 50% Rule: held {_days_held}d of {_entry_dte}d, "
                        f"only {pnl_pct:.0f}% — exit while buyers exist", "NORMAL"))
                    continue

            # ═══ PROFIT-BASED EXITS ═══

            # Rule 9: 10x+ — always take it
            if pnl_mult >= self.FULL_EXIT_10X:
                exits.append((key, f"🏆 10-BAGGER! +{pnl_pct:.0f}% — booking full profit", "NORMAL"))
                continue

            # Rule 8: 5x+ — full exit
            if pnl_mult >= self.FULL_EXIT_5X:
                exits.append((key, f"🎯 5x profit! +{pnl_pct:.0f}% — full exit", "NORMAL"))
                continue

            # ═══ LOSS-BASED EXITS ═══

            # Rule 10: Hard SL at 50%
            if pnl_pct <= -50:
                exits.append((key, f"🛑 HARD SL: {pnl_pct:.0f}% loss — max pain reached", "URGENT"))
                continue

            # Rule 14: 30% loss with DTE < 15 (was DTE < 7 — too late for NSE)
            if pnl_pct <= -30 and dte <= 15:
                exits.append((key, f"📉 Theta SL: {pnl_pct:.0f}% loss, DTE={dte} — no recovery time with liquidity", "URGENT"))
                continue

            # Rule 12: 20% loss + catalyst passed
            if pnl_pct <= -20 and catalyst_date:
                try:
                    if isinstance(catalyst_date, str):
                        cat_dt = datetime.strptime(catalyst_date, "%Y-%m-%d").date()
                    else:
                        cat_dt = catalyst_date.date() if hasattr(catalyst_date, 'date') else catalyst_date
                    if now_ist().date() > cat_dt:  # v25.5.5: IST
                        exits.append((key, f"📉 Thesis broken: catalyst passed, P&L={pnl_pct:.0f}%", "NORMAL"))
                        continue
                except Exception:
                    pass

            # ═══ TRAILING STOP ═══
            if pnl_mult >= (1 + self.TRAIL_ACTIVATION):
                trail_floor = peak * (1 - self.TRAIL_PCT)
                if current_premium <= trail_floor:
                    exits.append((key, 
                        f"📉 Trail stop: peak ₹{peak:.1f} → now ₹{current_premium:.1f} "
                        f"(floor ₹{trail_floor:.1f}), booking +{pnl_pct:.0f}%", "NORMAL"))
                    continue

            # ═══ MOONSHOT-SPECIFIC ═══
            if engine == "MOONSHOT":
                # Rule 16: Catalyst passed without significant move
                if catalyst_date:
                    try:
                        if isinstance(catalyst_date, str):
                            cat_dt = datetime.strptime(catalyst_date, "%Y-%m-%d").date()
                        else:
                            cat_dt = catalyst_date.date() if hasattr(catalyst_date, 'date') else catalyst_date
                        if now_ist().date() > cat_dt and pnl_pct < 50:  # v25.5.5: IST
                            exits.append((key, 
                                f"🌙 Moonshot thesis expired: catalyst passed, only +{pnl_pct:.0f}%", "NORMAL"))
                            continue
                    except Exception:
                        pass

                # Rule 17: Stock moved against us > 3%
                spot = spot_prices.get(symbol, 0)
                entry_spot = pos.get("entry_spot", 0)
                if spot > 0 and entry_spot > 0:
                    spot_move = (spot - entry_spot) / entry_spot * 100
                    if direction == "BULLISH" and spot_move < -3:
                        exits.append((key, 
                            f"🌙 Wrong direction: stock down {spot_move:.1f}%, thesis broken", "URGENT"))
                        continue
                    elif direction == "BEARISH" and spot_move > 3:
                        exits.append((key, 
                            f"🌙 Wrong direction: stock up +{spot_move:.1f}%, thesis broken", "URGENT"))
                        continue

        logger.info(
            f"🔍 EXIT ENGINE: Checked {len(positions)} positions, "
            f"{len(exits)} exits triggered"
        )
        return exits

    def reset_daily(self):
        """Reset daily tracking."""
        self.exit_log = []


# ═══════════════════════════════════════════════════════════════════════════════
#  v25.4.0: AUTONOMOUS PIPELINE — Queue → Rank → Execute
#  Zero human intervention. Bot finds, evaluates, and executes trades
#  across all three engines autonomously.
# ═══════════════════════════════════════════════════════════════════════════════

class AutonomousPipeline:
    """
    The brain that connects all engines into a single autonomous flow:
    
    EVERY 30 MINUTES (during market hours):
      1. QUEUE: All 10 pods propose trades → equity_queue
                FNOIntelEngine proposes → fno_queue
                MoonshotScanner proposes → moonshot_queue
      2. RANK:  Score every proposal (DVM + confidence + catalyst + regime)
                Apply cross-engine correlation filter (no double-exposure)
                Apply capital budget check per engine
      3. EXECUTE: Top N proposals get executed via Kite
                  GTT placed immediately for equity
                  SL order placed for F&O
                  Moonshots get fire-and-forget SL at 50%
    
    EVERY 5 MINUTES:
      - Check stops (trailing SL, dead money, time decay)
      - Sync positions with Kite (catch GTT-triggered exits)
    
    POST-MARKET (15:35):
      - Reconcile all positions
      - Calculate engine-level P&L
      - Generate 4PM PDF report
      - Queue AMO orders for next day
    """

    def __init__(self, sentinel):
        """
        sentinel: the GIRSentinel instance (has .swing, .fno, .kite, etc.)
        """
        self.sentinel = sentinel
        self.equity_queue = []       # Proposals from pod scans
        self.fno_queue = []          # Proposals from FNOIntelEngine
        # v25.5.0: moonshot merged into fno_queue
        self.execution_log = []      # Today's executed trades
        self._last_queue_time = None
        self._last_rank_time = None
        self._cycle_count = 0

    def queue_phase(self, scans, fno_intel=None, moonshot_scanner=None):
        """
        GIR PHASE 1: QUEUE — Dual-brain candidate collection.
        
        EquityBrain: builds equity_queue (with regime filters, pod system)
        FnoBrain: builds fno_queue INDEPENDENTLY (NO regime filters)
        
        Zero shared candidates between brains.
        """
        self.equity_queue = []
        self.fno_queue = []

        # ── EQUITY BRAIN: queue via pod system + DVM + confidence ──
        if hasattr(self.sentinel, 'equity_brain') and self.sentinel.equity_brain:
            self.equity_queue = self.sentinel.equity_brain.scan_and_queue(scans) or []
        else:
            # Fallback: original equity queueing
            if scans:
                _scan_iter = scans.items() if isinstance(scans, dict) else ((d.get("symbol",""), d) for d in scans if isinstance(d, dict))
                for symbol, data in _scan_iter:
                    if not isinstance(data, dict): continue
                    confidence = data.get("confidence", 0)
                    dvm = data.get("dvm_score", 0)
                    pod = get_pod_for_sector(symbol)
                    pod_name = [k for k, v in GRIFFIN_POD_CONFIG.items() if v == pod]
                    pod_name = pod_name[0] if pod_name else "SERVICES"
                    pod_conf_min = pod.get("confidence_min", 45)
                    pod_dvm_min = pod.get("dvm_min", 60)
                    if confidence >= pod_conf_min and dvm >= pod_dvm_min:
                        self.equity_queue.append({
                            "symbol": symbol, "engine": "EQUITY",
                            "confidence": confidence, "dvm": dvm, "pod": pod_name,
                            "ltp": data.get("ltp", 0), "atr": data.get("atr", 0),
                            "sl_atr_mult": pod.get("sl_atr_mult", 2.0),
                            "t2_atr_mult": pod.get("t2_atr_mult", 12.0),
                            "data": data,
                        })

        # ── F&O BRAIN: independent scan — NO equity regime filters ──
        if hasattr(self.sentinel, 'fno_brain') and self.sentinel.fno_brain:
            _kite = KiteSession.get()
            self.fno_queue = self.sentinel.fno_brain.scan_and_queue(scans, kite=_kite) or []
        else:
            # Fallback: FnoBrain not available — skip F&O queueing
            logger.warning("F&O BRAIN not initialized — skipping F&O queue")

        # ── GIR: NO cross-contamination — equity candidates do NOT auto-become F&O candidates ──
        # Each brain manages its own candidate pool independently

        self._last_queue_time = datetime.now()
        logger.info(
            f"📋 PIPELINE QUEUE: Equity={len(self.equity_queue)} | "
            f"F&O={len(self.fno_queue)} (dual-brain, zero shared candidates)"
        )

    def rank_phase(self):
        """
        PHASE 2: RANK — Score, deduplicate, and budget-check all proposals.
        
        Rules:
          - No duplicate symbols across engines (equity takes priority)
          - Equity: max 10 positions total
          - Safe F&O: max 3 active positions
          - Moonshot: max 3 active tickets
          - Cross-correlation: max 2 stocks from same sector across all engines
        """
        # Deduplicate: if a symbol appears in multiple engines, keep highest-priority
        seen_symbols = set()
        
        # Get current positions across all books
        eq_positions = set()
        if hasattr(self.sentinel, 'swing'):
            eq_positions = set(self.sentinel.swing.book.get("positions", {}).keys())
        
        fno_positions = set()
        if hasattr(self.sentinel, 'fno') and hasattr(self.sentinel.fno, 'fno'):
            fno_positions = set(self.sentinel.fno.fno.book.get("positions", {}).keys())

        # ── Rank equity queue ──
        ranked_equity = []
        for prop in sorted(self.equity_queue, key=lambda x: x["confidence"], reverse=True):
            sym = prop["symbol"]
            if sym in seen_symbols or sym in eq_positions:
                continue
            seen_symbols.add(sym)
            ranked_equity.append(prop)

        # ── Rank F&O queue ──
        # v25.5.2: F&O NOT deduped against equity — shares and options are different instruments
        ranked_fno = []
        _fno_seen = set()  # Only dedup within F&O itself
        for prop in sorted(self.fno_queue, key=lambda x: x.get("score", 0), reverse=True):
            sym = prop["symbol"]
            if sym in _fno_seen:
                continue
            _fno_seen.add(sym)
            ranked_fno.append(prop)

        # ── Rank moonshot queue ──
        # v25.5.0-merged: ranked_moonshot = []
        # v25.5.0: moonshot merged into fno_queue above
            # v25.5.0-merged: sym = prop["symbol"]
            # v25.5.0-merged: if sym in seen_symbols:
                # v25.5.0-merged: continue
            # v25.5.0-merged: seen_symbols.add(sym)
            # v25.5.0-merged: ranked_moonshot.append(prop)

        # ── Sector concentration filter (max 2 per sector across all engines) ──
        sector_count = defaultdict(int)
        # Count existing positions by sector
        for sym in eq_positions:
            pod = get_pod_for_sector(sym)
            pod_name = [k for k, v in GRIFFIN_POD_CONFIG.items() if v == pod][0]
            sector_count[pod_name] += 1

        final_equity = []
        for prop in ranked_equity:
            if sector_count[prop["pod"]] < 2:
                final_equity.append(prop)
                sector_count[prop["pod"]] += 1

        final_fno = []
        _fno_sector_count = defaultdict(int)  # v25.5.2-fix: F&O independent of equity
        for prop in ranked_fno:
            pod_name = prop.get("pod", "SERVICES")
            if _fno_sector_count.get(pod_name, 0) < 3:  # F&O gets slightly more room
                final_fno.append(prop)
                _fno_sector_count[pod_name] = _fno_sector_count.get(pod_name, 0) + 1

        final_moonshot = []  # v25.5.2: moonshot merged into fno_queue

        # Budget check: how many new positions each engine can take
        max_new_equity = max(0, 10 - len(eq_positions))
        max_new_fno = max(0, MAX_FNO_POS - len(fno_positions))  # v25.6.0: use MAX_FNO_POS (5) not hardcoded 3
        max_new_moonshot = 3  # Moonshot scanner handles its own limit

        self.equity_queue = final_equity[:max_new_equity]
        self.fno_queue = final_fno[:max_new_fno]
        # v25.5.0: moonshot merged into fno_queue
        
        self._last_rank_time = datetime.now()
        logger.info(
            f"📊 PIPELINE RANK: Equity→{len(self.equity_queue)} | "
            # v25.5.0-merged: f"F&O→{len(self.fno_queue)} | Moonshot→{len(self.moonshot_queue)} "
            f"(after dedup + sector filter + budget)"
        )

    def execute_phase(self, kite=None):
        """
        PHASE 3: EXECUTE — Place orders for top-ranked proposals.
        
        Equity: via existing swing trader (LIMIT order + GTT)
        Safe F&O: via LiveFNOAdapter (LIMIT order + SL)
        Moonshot: via LiveFNOAdapter (MKT order for small premium, SL at 50%)
        
        Returns list of executed trades for Telegram notification.
        """
        executed = []

        # v25.5.0: Capital waterfall — check affordability, skip to next if can't afford
        _eq_capital = 0
        _fno_capital = 0
        # v25.5.0: moonshot capital merged into _fno_capital
        if kite:
            try:
                _margins = kite.margins("equity")
                _total = _margins.get("available", {}).get("live_balance", 0) + _margins.get("available", {}).get("collateral", 0)
                if _total <= 0:
                    _total = _margins.get("net", 0)
                _alloc = CapitalAllocator.allocate(_total, kite=kite)
                _eq_capital = _alloc.get("equity", _alloc.get("swing", 0))
                _fno_capital = _alloc.get("fno", 0)  # v25.5.0: unified F&O (was safe_fno + moonshot)
                # v25.5.0: moonshot merged — see _fno_capital
                logger.info(f"💰 Pipeline capital: Eq=₹{_eq_capital:,.0f} F&O=₹{_fno_capital:,.0f} Moon=₹{_fno_capital:,.0f}")
            except Exception as _cap_err:
                logger.warning(f"Pipeline capital check: {_cap_err}")
                _eq_capital = 50000  # Safe fallback
                _fno_capital = 15000  # v25.5.0: unified fallback (was 10000+5000)
                # v25.5.0: moonshot merged into fno fallback
        else:
            logger.info("💰 Pipeline: No Kite — queueing candidates for next session")

        _eq_spent = 0
        _fno_spent = 0
        # v25.5.0: moonshot spent merged into _fno_spent

        # ── Execute equity trades (capital waterfall) ──
        for prop in self.equity_queue:
            try:
                sym = prop["symbol"]
                ltp = prop.get("ltp", 0)
                # v25.5.0: Fetch live price if LTP missing (intel engine candidates)
                if ltp <= 0 and kite:
                    try:
                        _q = kite.ltp(f"NSE:{sym}")
                        ltp = _q.get(f"NSE:{sym}", {}).get("last_price", 0)
                        prop["ltp"] = ltp
                        logger.info(f"📡 Pipeline fetched LTP for {sym}: ₹{ltp}")
                    except:
                        pass
                if ltp <= 0:
                    if not kite:
                        # No Kite (weekend) — still queue for later
                        executed.append({"engine": "EQUITY", "symbol": sym, "pod": prop.get("pod"),
                                        "confidence": prop.get("confidence"), "action": "PRE_QUEUED"})
                        logger.info(f"🌙 PIPELINE EQUITY: {sym} pre-queued (no Kite — will execute at market open)")
                    continue
                
                # Capital check: can we afford this stock?
                _kelly_pct = min(0.15, max(0.05, prop.get("confidence", 50) / 500))
                _position_size = _eq_capital * _kelly_pct
                _qty = max(1, int(_position_size / ltp))
                _cost = _qty * ltp
                
                if _eq_spent + _cost > _eq_capital:
                    logger.info(f"⏭️ PIPELINE EQUITY: {sym} skipped — insufficient capital "
                               f"(need ₹{_cost:,.0f}, remaining ₹{_eq_capital - _eq_spent:,.0f})")
                    continue
                
                _eq_spent += _cost
                executed.append({
                    "engine": "EQUITY", "symbol": sym, "pod": prop.get("pod"),
                    "confidence": prop.get("confidence"), "action": "BUY_QUEUED",
                    "qty": _qty, "ltp": ltp, "cost": _cost,
                })
                logger.info(f"✅ PIPELINE EQUITY: {sym} x{_qty} ≈₹{_cost:,.0f} queued "
                           f"(conf={prop.get('confidence')}, remaining=₹{_eq_capital - _eq_spent:,.0f})")
            except Exception as e:
                logger.warning(f"Pipeline equity execute [{prop.get('symbol')}]: {e}")

        if _eq_spent == 0 and _eq_capital > 0 and kite:
            logger.info("💰 PIPELINE: No equity trades affordable at current prices — waiting for capital")

        # ── Execute safe F&O trades via FNOTrader ──
        _fno_trader = None
        if hasattr(self.sentinel, 'fno'):
            _fno_trader = self.sentinel.fno  # Use LiveFNOAdapter (not raw FNOTrader) for proper order+GTT handling

        for prop in self.fno_queue:
            try:
                sym = prop["symbol"]
                if _fno_spent >= _fno_capital and kite:
                    logger.info(f"⏭️ PIPELINE F&O: {sym} skipped — F&O capital exhausted")
                    continue

                _direction = prop.get("direction", "BULLISH")
                _score = prop.get("score", 0)
                # Map score to confidence level for FNOTrader
                if _score >= 80:
                    _conf = "STRONG_BULLISH" if "BULL" in _direction else "STRONG_BEARISH"
                elif _score >= 50:
                    _conf = "BULLISH" if "BULL" in _direction else "BEARISH"
                else:
                    _conf = "MODERATE"

                # Get spot price
                _spot = 0
                if kite:
                    try:
                        _q = kite.ltp(f"NSE:{sym}")
                        _spot = _q.get(f"NSE:{sym}", {}).get("last_price", 0)
                    except:
                        pass
                if _spot <= 0:
                    _spot = prop.get("data", {}).get("price", 0)
                if _spot <= 0:
                    logger.info(f"⏭️ PIPELINE F&O: {sym} skipped — no spot price")
                    continue

                # Place F&O order via FNOTrader
                if _fno_trader and hasattr(_fno_trader, 'enter'):
                    _fno_result = _fno_trader.enter(sym, _spot, _direction, source=f"PIPELINE_{prop.get('catalyst','TECH')}", confidence=_conf)
                    if _fno_result:
                        _cost = _fno_result.get("cost", 0)
                        _fno_spent += _cost
                        executed.append({
                            "engine": "SAFE_FNO", "symbol": sym,
                            "catalyst": prop.get("catalyst"), "score": _score,
                            "action": "FNO_PLACED",
                            "strike": _fno_result.get("strike"),
                            "opt_type": _fno_result.get("opt_type"),
                            "premium": _fno_result.get("premium"),
                            "cost": _cost,
                        })
                        logger.info(f"✅ PIPELINE F&O: {sym} {_fno_result.get('strike')}{_fno_result.get('opt_type')} placed (cost=₹{_cost:,.0f})")
                    else:
                        logger.info(f"⏭️ PIPELINE F&O: {sym} — FNOTrader rejected (capital/position limit)")
                else:
                    logger.info(f"⏭️ PIPELINE F&O: {sym} — no FNOTrader available")
            except Exception as e:
                logger.warning(f"Pipeline F&O execute [{prop.get('symbol')}]: {e}")

        # ── Execute moonshot trades (capital waterfall) ──
        # v25.5.0-merged: for prop in self.moonshot_queue:
            # v25.5.0-merged: try:
                # v25.5.0-merged: sym = prop["symbol"]
                # v25.5.0-merged: if _moon_spent >= _moon_capital and kite:
                    # v25.5.0-merged: logger.info(f"⏭️ PIPELINE MOONSHOT: {sym} skipped — moonshot capital exhausted")
                    # v25.5.0-merged: continue
                
                # v25.5.0-merged: executed.append({
                    # v25.5.0-merged: "engine": "FNO_MOONSHOT",  # v25.5.0: unified "symbol": sym,
                    # v25.5.0-merged: "catalyst": prop.get("catalyst"), "score": prop.get("score"),
                    # v25.5.0-merged: "action": "MOONSHOT_QUEUED" if kite else "MOON_PRE_QUEUED",
                # v25.5.0-merged: })
                # v25.5.0-merged: logger.info(f"🚀 PIPELINE MOONSHOT: {sym} queued for deep OTM entry (score={prop.get('score')})")
            # v25.5.0-merged: except Exception as e:
                # v25.5.0-merged: logger.warning(f"Pipeline moonshot execute [{prop.get('symbol')}]: {e}")

        self.execution_log.extend(executed)
        self._cycle_count += 1
        
        logger.info(
            f"⚡ PIPELINE EXECUTE: {len(executed)} trades queued | "
            f"Cycle #{self._cycle_count}"
        )
        return executed

    def run_full_cycle(self, scans, fno_intel=None, moonshot_scanner=None, kite=None):
        """Run Queue → Rank → Execute pipeline."""
        logger.info("PIPELINE: QUEUE phase...")
        self.queue_phase(scans, fno_intel, moonshot_scanner)
        self.rank_phase()
        logger.info(f"PIPELINE: RANK done — eq={len(self.equity_queue)} fno={len(self.fno_queue)}")
        logger.info(f"PIPELINE: EXECUTE phase... eq={len(self.equity_queue)} fno={len(self.fno_queue)}")
        executed = self.execute_phase(kite)
        logger.info(f"PIPELINE: DONE — {len(executed)} trades executed")
        return executed

    def get_daily_summary(self):
        """Return summary for the 4PM PDF report."""
        eq_trades = [t for t in self.execution_log if t["engine"] == "EQUITY"]
        fno_trades = [t for t in self.execution_log if t["engine"] == "SAFE_FNO"]
        moon_trades = [t for t in self.execution_log if t["engine"] == "MOONSHOT"]
        return {
            "total_cycles": self._cycle_count,
            "equity_trades": len(eq_trades),
            "fno_trades": len(fno_trades),
            "moonshot_trades": len(moon_trades),
            "equity_symbols": [t["symbol"] for t in eq_trades],
            "fno_symbols": [t["symbol"] for t in fno_trades],
            "moonshot_symbols": [t["symbol"] for t in moon_trades],
        }

    def reset_daily(self):
        """Reset for new trading day."""
        self.equity_queue = []
        self.fno_queue = []
        # v25.5.0: moonshot merged into fno_queue
        self.execution_log = []
        self._cycle_count = 0


# ═══════════════════════════════════════════════════════════════════════════════
#  v25.4.0: TELEGRAM GATEKEEPER — EXACTLY 4 MESSAGES PER DAY
#  
#  Message 1: 08:30 AM — Morning Brief (text)
#  Message 2: 12:00 PM — Midday Portfolio PDF
#  Message 3: TRADE EXECUTED — immediate (only when money moves)
#  Message 4: 04:00 PM — EOD Full Report PDF
#  
#  ALL other send_telegram calls get SILENCED (logged but not sent).
# ═══════════════════════════════════════════════════════════════════════════════

# --- FORWARD UTILITY DEFS (needed before TelegramGatekeeper) ---
def now_ist():  return datetime.now(IST)
def today_str():return now_ist().strftime("%Y-%m-%d")
def _t(s): return datetime.strptime(s,"%H:%M").time()
# --- END FORWARD DEFS ---
class TelegramGatekeeper:
    """
    Controls ALL Telegram output. Only 4 message types are allowed per day.
    Everything else gets logged to file but NOT sent to Telegram.
    
    Allowed messages:
      1. MORNING_BRIEF  — 08:30 AM, one text message with:
         - VIX regime, capital split (3 engines), holdings P&L
         - Catalyst calendar, pod activity summary
         - Pipeline status (queue depth per engine)
      2. MIDDAY_PDF     — 12:00 PM, one PDF with full portfolio
      3. TRADE_EXECUTED  — Immediate, ONLY when a real order fills
         - Symbol, price, quantity, engine, SL/TP levels
         - This is the ONLY real-time message
      4. EOD_PDF        — 04:00 PM, comprehensive PDF report with:
         - Full P&L, all 3 engines, pipeline summary
         - Moonshot status, catalyst hits/misses
         - Next day preview
    
    Everything else → logger.info() only (no Telegram).
    """

    ALLOWED_TYPES = {"MORNING_BRIEF", "MIDDAY_PDF", "TRADE_EXECUTED", "EOD_PDF"}

    def __init__(self):
        self.sent_today = defaultdict(int)   # Track count per type
        self.blocked_count = 0               # How many messages blocked today
        self._date = now_ist().date()  # v25.5.5: IST

    def _check_new_day(self):
        """Reset counters at midnight."""
        today = now_ist()  # v25.5.4-fix: use IST not UTC.date()
        if today != self._date:
            self.sent_today = defaultdict(int)
            self.blocked_count = 0
            self._date = today

    def can_send(self, msg_type):
        """
        Check if this message type is allowed right now.
        
        Rules:
          - MORNING_BRIEF: max 1/day
          - MIDDAY_PDF: max 1/day
          - TRADE_EXECUTED: unlimited (real trades must always notify)
          - EOD_PDF: max 1/day
          - Anything else: BLOCKED
        """
        self._check_new_day()

        if msg_type not in self.ALLOWED_TYPES:
            self.blocked_count += 1
            return False

        if msg_type == "TRADE_EXECUTED":
            return True  # Always allow trade notifications

        if self.sent_today[msg_type] >= 1:
            return False  # Already sent today

        return True

    def record_sent(self, msg_type):
        """Record that a message was sent."""
        self._check_new_day()
        self.sent_today[msg_type] += 1

    def get_stats(self):
        """Return gatekeeper stats for logging."""
        return {
            "sent": dict(self.sent_today),
            "blocked": self.blocked_count,
            "date": str(self._date),
        }


# Global gatekeeper instance
_telegram_gatekeeper = TelegramGatekeeper()


def _get_pod_sl_tp(sector_text, price, atr):
    """Calculate pod-specific SL, T1, T2 using sector's ATR multipliers."""
    pod = _get_pod_for_sector(sector_text)
    sl_mult = pod["sl_atr_mult"]
    t1_mult = pod["t1_atr_mult"]
    t2_mult = pod["t2_atr_mult"]
    
    if atr > 0:
        sl = round(price * (1 - min(max(atr * sl_mult / price, MIN_SL_PERCENT), SCAN_SL_PERCENT)), 2)
        t1 = round(price + t1_mult * atr, 2)
        t2 = round(price + t2_mult * atr, 2)
    else:
        sl = round(price * (1 - 0.02), 2)
        t1 = round(price * 1.05, 2)
        t2 = round(price * 1.12, 2)
    
    return sl, t1, t2, pod


# ═══════════════════════════════════════════════════════════════════════════════
#  GRIFFIN VIX-BASED POD CAPITAL ALLOCATION
#  Fear → defensive pods get more capital | Greed → aggressive pods dominate
# ═══════════════════════════════════════════════════════════════════════════════

GRIFFIN_REGIME_ALLOCATION = {
    # VIX regime → {pod_group: allocation_pct}
    "EXTREME_FEAR": {"defensive": 0.70, "cyclical": 0.20, "high_beta": 0.10},
    "FEAR":         {"defensive": 0.55, "cyclical": 0.30, "high_beta": 0.15},
    "CAUTION":      {"defensive": 0.40, "cyclical": 0.35, "high_beta": 0.25},
    "NEUTRAL":      {"defensive": 0.30, "cyclical": 0.40, "high_beta": 0.30},
    "CONFIDENCE":   {"defensive": 0.20, "cyclical": 0.40, "high_beta": 0.40},
    "EUPHORIA":     {"defensive": 0.15, "cyclical": 0.35, "high_beta": 0.50},
}

GRIFFIN_POD_GROUPS = {
    "defensive": ["BANKING", "IT", "PHARMA", "FMCG"],
    "cyclical":  ["AUTO", "ENERGY", "CHEMICALS"],
    "high_beta": ["METALS", "INFRA", "SERVICES"],
}

def _get_vix_regime(vix_value):
    """Convert VIX number to Griffin regime name."""
    if vix_value >= 30: return "EXTREME_FEAR"
    elif vix_value >= 24: return "FEAR"
    elif vix_value >= 18: return "CAUTION"
    elif vix_value >= 14: return "NEUTRAL"
    elif vix_value >= 10: return "CONFIDENCE"
    else: return "EUPHORIA"

def _get_pod_capital_allocation(total_capital, vix_value):
    """
    Distribute capital across 10 pods based on VIX regime.
    Returns: {pod_name: max_capital_for_pod}
    """
    regime = _get_vix_regime(vix_value)
    alloc = GRIFFIN_REGIME_ALLOCATION.get(regime, GRIFFIN_REGIME_ALLOCATION["NEUTRAL"])
    result = {}
    for group, pods in GRIFFIN_POD_GROUPS.items():
        group_capital = total_capital * alloc[group]
        per_pod = group_capital / len(pods)
        for pod in pods:
            result[pod] = round(per_pod, 2)
    return result, regime

def _get_pod_position_size(symbol, price, capital, vix_value, atr=0):
    """
    Calculate position size for a stock based on its pod's capital allocation.
    Uses Kelly criterion within the pod's allocated capital.
    """
    sector = ""
    # Try to get sector from scan result or TrendLyne
    pod = _get_pod_for_sector(sector)
    pod_name = [k for k, v in GRIFFIN_POD_CONFIG.items() if v == pod][0] if pod else "SERVICES"
    
    pod_alloc, regime = _get_pod_capital_allocation(capital, vix_value)
    pod_capital = pod_alloc.get(pod_name, capital / 10)
    
    # Max position = pod capital * position sizing (35% as per Standard Variation B)
    max_position = pod_capital * 0.35
    qty = int(max_position / price) if price > 0 else 0
    return max(qty, 1), pod_capital, regime


# ═══════════════════════════════════════════════════════════════════════════════
#  CATALYST CALENDAR — Pre-computed events per pod (the EDGE engine)
# ═══════════════════════════════════════════════════════════════════════════════

GRIFFIN_RBI_DATES = ["2026-04-09", "2026-06-06", "2026-08-08", "2026-10-08", "2026-12-05", "2027-02-06"]
GRIFFIN_AUTO_SALES = [f"2026-{m:02d}-01" for m in range(4, 13)] + [f"2027-{m:02d}-01" for m in range(1, 4)]
GRIFFIN_BUDGET_DATES = ["2027-02-01"]

def _get_upcoming_catalysts(days_ahead=7):
    """Get all upcoming catalysts across all 10 pods."""
    today = now_ist().date()  # v25.5.5: IST
    end = today + timedelta(days=days_ahead)
    catalysts = []
    
    for d in GRIFFIN_RBI_DATES:
        dt = datetime.strptime(d, "%Y-%m-%d").date()
        if today <= dt <= end:
            catalysts.append(f"🏦 RBI MPC decision on {dt.strftime('%d %b')}")
    
    for d in GRIFFIN_AUTO_SALES:
        dt = datetime.strptime(d, "%Y-%m-%d").date()
        if today <= dt <= end:
            catalysts.append(f"🚗 Auto monthly sales data on {dt.strftime('%d %b')}")
    
    for d in GRIFFIN_BUDGET_DATES:
        dt = datetime.strptime(d, "%Y-%m-%d").date()
        if today <= dt <= end:
            catalysts.append(f"🏗️ Union Budget on {dt.strftime('%d %b')}")
    
    return catalysts


# ═══════════════════════════════════════════════════════════════════════════════
#  GRIFFIN CONFIDENCE FILTER — Pod-specific minimum confidence
#  Each pod has its own threshold. Defensive pods accept lower confidence
#  (safer stocks), aggressive pods need higher confidence (riskier stocks)
# ═══════════════════════════════════════════════════════════════════════════════

def _griffin_confidence_check(confidence, sector_text):
    """Check if confidence meets the pod's minimum threshold."""
    pod = _get_pod_for_sector(sector_text)
    min_conf = pod.get("confidence_min", 45)
    return confidence >= min_conf, min_conf

def _griffin_dvm_check(dvm_score, sector_text):
    """Check if DVM score meets the pod's minimum threshold."""
    pod = _get_pod_for_sector(sector_text)
    min_dvm = pod.get("dvm_min", 60)
    return dvm_score >= min_dvm, min_dvm

