#  ADVANCED TRADING ENGINE (v23.8.0: inlined from advanced_trading_engine.py)
#  TrailingStopLoss + KellyCriterion + PortfolioAnalyzer + BacktestEngine
# ═══════════════════════════════════════════════════════════════════════════

class TrailingStopLoss:
    """
    Manages trailing stop losses for all open positions.
    Called every rapid scan (5 min) and every full scan (30 min).
    """

    # Trail percentage by strategy type
    TRAIL_PCT = {
        "intraday": 0.025,   # 2.5% trail — tight for intraday
        "swing":    0.0375,  # 3.75% trail — medium for swing
        "longterm": 0.05,    # 5% trail — wider for long term
    }

    # Only start trailing after this profit % is reached
    ACTIVATION_PCT = {
        "intraday": 1.5,   # Start trailing after 1.5% profit
        "swing":    2.5,   # Start trailing after 2.5% profit
        "longterm": 5.0,   # Start trailing after 5% profit
    }

    @classmethod
    def update_trailing_sl(cls, trader, ltp_data, send_telegram_fn):
        """
        Update trailing stop loss for all positions in a trader.

        Args:
            trader: BasePaperTrader or LiveEquityTrader instance
            ltp_data: dict of {symbol: current_price}
            send_telegram_fn: send_telegram function

        Returns: list of positions where SL was updated
        """
        updated = []
        strategy = getattr(trader, 'name', 'swing')
        trail_pct = cls.TRAIL_PCT.get(strategy, 0.0375)
        activation_pct = cls.ACTIVATION_PCT.get(strategy, 2.5)

        for sym, pos in list(trader.book.get("positions", {}).items()):
            cmp = ltp_data.get(sym, 0)
            if cmp <= 0:
                continue

            entry_price = pos.get("entry_price", 0)
            current_sl = pos.get("stop_loss", 0)

            if entry_price <= 0:
                continue

            # Current profit %
            profit_pct = (cmp - entry_price) / entry_price * 100

            # Only trail if profit exceeds activation threshold
            if profit_pct < activation_pct:
                continue

            # Calculate trailing SL
            # Trail from the HIGH price seen, not from current price
            highest_price = pos.get("highest_price", cmp)
            if cmp > highest_price:
                highest_price = cmp
                pos["highest_price"] = highest_price

            trail_sl = round(highest_price * (1 - trail_pct), 2)

            # SL only moves UP, never down
            if trail_sl > current_sl:
                old_sl = current_sl
                pos["stop_loss"] = trail_sl
                updated.append({
                    "symbol": sym,
                    "old_sl": old_sl,
                    "new_sl": trail_sl,
                    "cmp": cmp,
                    "entry": entry_price,
                    "profit_pct": round(profit_pct, 2),
                    "highest": highest_price,
                })

                logger.info(
                    "📈 TRAIL SL [{}] {} | SL: ₹{} → ₹{} | "
                    "CMP: ₹{} | Profit: +{:.1f}% | High: ₹{}".format(
                        strategy.upper(), sym, old_sl, trail_sl,
                        cmp, profit_pct, highest_price))

        # Save if anything changed
        if updated:
            trader._save()

            # Send consolidated alert (not per-stock spam)
            # v24: ONLY send trailing SL alerts for SIGNIFICANT moves (>1% SL change)
            # Minor trailing adjustments (0.1-0.3%) are logged but NOT sent to Telegram
            _significant_updates = [u for u in updated if u["new_sl"] > u["old_sl"] * 1.01]
            if _significant_updates and len(_significant_updates) <= 3:
                lines = []
                for u in _significant_updates:
                    # v24.1.4: Only say "Profit locked" if SL is actually above entry
                    _lock_msg = "\U0001F4CC Profit locked automatically" if all(
                        u.get("new_sl", 0) >= u.get("entry", float('inf'))
                        for u in _significant_updates
                    ) else "\U0001F4CC SL tightened — loss reduced"
                    lines.append(
                        "  {} `{}` SL: ₹{} \u2192 ₹{} (+{:.1f}%)".format(
                            "\U0001F512", u["symbol"], u["old_sl"],
                            u["new_sl"], u["profit_pct"]))
                nl = "\n"
                send_telegram_fn(
                    "\U0001F4C8 *TRAILING SL UPDATED — {}*\n".format(
                        strategy.upper())
                    + nl.join(lines) + "\n"
                    + _lock_msg,
                    priority="trade"
                )
            elif _significant_updates:
                send_telegram_fn(
                    "\U0001F4C8 *TRAILING SL — {} positions updated ({})*\n"
                    "\U0001F4CC All profit locked automatically".format(
                        len(_significant_updates), strategy.upper()),
                    priority="trade"
                )

        return updated

    @classmethod
    def update_all(cls, sentinel, ltp_data, send_telegram_fn):
        """Update trailing SL for all strategies."""
        all_updated = []
        for trader in [sentinel.intraday, sentinel.swing, sentinel.longterm]:
            try:
                updates = cls.update_trailing_sl(trader, ltp_data, send_telegram_fn)
                all_updated.extend(updates)
            except Exception as e:
                logger.error("Trailing SL [{}]: {}".format(
                    getattr(trader, 'name', '?'), e))
        return all_updated


# ══════════════════════════════════════════════════════════════
#  2. KELLY CRITERION POSITION SIZING
#     Mathematically optimal bet size.
#
#     Kelly % = W - (1-W)/R
#     W = win rate (e.g., 0.65 = 65%)
#     R = win/loss ratio (avg win / avg loss)
#
#     If Kelly says 25%, you risk 25% of capital per trade.
#     We use HALF KELLY (safer) — 12.5% in this example.
#
#     Ed Thorp used this to beat blackjack AND Wall Street.
# ══════════════════════════════════════════════════════════════

class KellyCriterion:
    """
    Calculates optimal position size based on actual trading history.
    Uses Half Kelly for safety (full Kelly is too aggressive).
    """

    # Minimum trades needed before Kelly kicks in
    MIN_TRADES = 10

    # Maximum Kelly fraction allowed (safety cap)
    MAX_KELLY = 0.15  # Never risk more than 15% per trade

    # Minimum Kelly fraction (floor)
    MIN_KELLY = 0.05  # v24.1.3: 5% floor (was 0.5%) — matches LiveEquityTrader

    @classmethod
    def calculate(cls, trader):
        """
        Calculate Kelly fraction for a trader based on trade history.

        Returns: {
            'kelly_full': float,     # Full Kelly %
            'kelly_half': float,     # Half Kelly % (what we use)
            'win_rate': float,       # Actual win rate
            'avg_win': float,        # Average winning trade
            'avg_loss': float,       # Average losing trade
            'rr_ratio': float,       # Reward/Risk ratio
            'trades_used': int,      # Number of trades in calculation
            'recommendation': str,   # Human-readable
        }
        """
        closed = [t for t in trader.book.get("trades", []) if t.get("status") == "CLOSED"]

        # v24.1.3 FIX: Exclude KITE_ADOPTED and poisoned trades from Kelly
        # KITE_ADOPTED positions were not bot-initiated — their P&L doesn't
        # reflect the bot's actual trading edge. Including them poisons WR to 0%.
        # Also exclude trades with source "ZOMBIE" or no source (old bot remnants).
        _clean_closed = []
        for t in closed:
            _src = t.get("source", "")
            # Skip adopted positions
            if "KITE_ADOPTED" in _src or "ADOPTED" in _src:
                continue
            # Skip trades with zero entry price (corrupted)
            if t.get("entry_price", 0) <= 0 and t.get("price", 0) <= 0:
                continue
            _clean_closed.append(t)

        # Use clean trades if we have enough, otherwise fall back to all trades
        if len(_clean_closed) >= 5:
            closed = _clean_closed
            logger.debug(f"Kelly: Using {len(closed)} clean trades (excluded {len([t for t in trader.book.get('trades', []) if t.get('status') == 'CLOSED']) - len(closed)} adopted/corrupt)")
        # If all trades are adopted, use defaults instead of 0% WR

        # Not enough history — use default 2% risk
        if len(closed) < cls.MIN_TRADES:
            return {
                "kelly_full": 0.02,
                "kelly_half": 0.01,
                "win_rate": 50.0,
                "avg_win": 0,
                "avg_loss": 0,
                "rr_ratio": 1.0,
                "trades_used": len(closed),
                "recommendation": "Default 2% risk (need {} more trades for Kelly)".format(
                    cls.MIN_TRADES - len(closed)),
            }

        wins = [t for t in closed if t.get("pnl", 0) > 0]
        losses = [t for t in closed if t.get("pnl", 0) <= 0]

        win_rate = len(wins) / len(closed) if closed else 0.5
        avg_win = sum(t["pnl"] for t in wins) / len(wins) if wins else 0
        avg_loss = abs(sum(t["pnl"] for t in losses) / len(losses)) if losses else 1

        # Reward/Risk ratio
        rr_ratio = avg_win / avg_loss if avg_loss > 0 else 1.0

        # Kelly formula: K = W - (1-W)/R
        if rr_ratio > 0:
            kelly_full = win_rate - (1 - win_rate) / rr_ratio
        else:
            kelly_full = 0

        # Half Kelly (safer)
        kelly_half = kelly_full / 2

        # Apply caps
        kelly_half = max(cls.MIN_KELLY, min(cls.MAX_KELLY, kelly_half))

        # If Kelly is negative, it means you're losing money — reduce to minimum
        if kelly_full <= 0:
            kelly_half = cls.MIN_KELLY
            recommendation = "Kelly NEGATIVE ({:.1f}%) — losing edge. Minimum size until stats improve".format(
                kelly_full * 100)
        elif kelly_half < 0.01:
            recommendation = "Small edge — using {:.1f}% per trade".format(kelly_half * 100)
        elif kelly_half < 0.05:
            recommendation = "Good edge — using {:.1f}% per trade".format(kelly_half * 100)
        else:
            recommendation = "Strong edge — using {:.1f}% per trade (capped at {}%)".format(
                kelly_half * 100, cls.MAX_KELLY * 100)

        return {
            "kelly_full": round(kelly_full, 4),
            "kelly_half": round(kelly_half, 4),
            "win_rate": round(win_rate * 100, 1),
            "avg_win": round(avg_win, 2),
            "avg_loss": round(avg_loss, 2),
            "rr_ratio": round(rr_ratio, 2),
            "trades_used": len(closed),
            "recommendation": recommendation,
        }

    @classmethod
    def optimal_qty(cls, trader, price, sl):
        """
        Calculate optimal quantity using Kelly Criterion.
        Replaces the fixed 2% risk calculation.

        Returns: qty (int)
        """
        kelly = cls.calculate(trader)
        available = trader.book.get("available", 0)
        risk_per_share = abs(price - sl)

        if risk_per_share <= 0 or available <= 0:
            return 0

        # Kelly-sized position
        risk_amount = available * kelly["kelly_half"]
        qty = max(1, int(risk_amount / risk_per_share))

        # Cap at 15% of available capital per position
        max_cost = available * 0.15
        if qty * price > max_cost:
            qty = max(1, int(max_cost / price))

        return qty


