#  3. PORTFOLIO ANALYZER
#     Checks if all positions are in same sector (dangerous)
#     Calculates correlation and concentration risk
# ══════════════════════════════════════════════════════════════

class PortfolioAnalyzer:
    """
    Analyses portfolio for concentration risk and sector correlation.
    Included in PDF reports.
    """

    # Sector mapping for common F&O stocks
    SECTOR_MAP = {
        # Banking
        "HDFCBANK": "Banking", "ICICIBANK": "Banking", "SBIN": "Banking",
        "KOTAKBANK": "Banking", "AXISBANK": "Banking", "INDUSINDBK": "Banking",
        "BANKBARODA": "Banking", "PNB": "Banking", "CANBK": "Banking",
        "FEDERALBNK": "Banking", "IDFCFIRSTB": "Banking", "BANDHANBNK": "Banking",
        # IT
        "TCS": "IT", "INFY": "IT", "WIPRO": "IT", "HCLTECH": "IT",
        "TECHM": "IT", "LTIM": "IT", "PERSISTENT": "IT", "COFORGE": "IT",
        "MPHASIS": "IT", "TATAELXSI": "IT",
        # Pharma
        "SUNPHARMA": "Pharma", "DRREDDY": "Pharma", "CIPLA": "Pharma",
        "DIVISLAB": "Pharma", "AUROPHARMA": "Pharma", "LUPIN": "Pharma",
        "BIOCON": "Pharma", "ZYDUSLIFE": "Pharma",
        # Auto
        "TATAMOTORS": "Auto", "M&M": "Auto", "MARUTI": "Auto",
        "BAJAJ-AUTO": "Auto", "EICHERMOT": "Auto", "HEROMOTOCO": "Auto",
        # Energy
        "RELIANCE": "Energy", "ONGC": "Energy", "BPCL": "Energy",
        "COALINDIA": "Energy", "NTPC": "Energy", "POWERGRID": "Energy",
        "ADANIGREEN": "Energy", "TATAPOWER": "Energy", "JSWENERGY": "Energy",
        # FMCG
        "HINDUNILVR": "FMCG", "ITC": "FMCG", "NESTLEIND": "FMCG",
        "BRITANNIA": "FMCG", "DABUR": "FMCG", "MARICO": "FMCG",
        "GODREJCP": "FMCG", "TATACONSUM": "FMCG",
        # Metal
        "TATASTEEL": "Metal", "JSWSTEEL": "Metal", "HINDALCO": "Metal",
        "VEDL": "Metal", "SAIL": "Metal", "NMDC": "Metal",
        # Infra/Cement
        "LT": "Infra", "ULTRACEMCO": "Cement", "GRASIM": "Cement",
        "ADANIENT": "Infra", "ADANIPORTS": "Infra", "DLF": "Realty",
        # Finance (Non-Bank)
        "BAJFINANCE": "Finance", "BAJAJFINSV": "Finance",
        "CHOLAFIN": "Finance", "M&MFIN": "Finance", "MUTHOOTFIN": "Finance",
        # Telecom
        "BHARTIARTL": "Telecom", "JIOFIN": "Telecom",
        # Index
        "NIFTY": "Index", "BANKNIFTY": "Index",
    }

    @classmethod
    def analyse(cls, sentinel):
        """
        Analyse all open positions for concentration risk.

        Returns: {
            'total_positions': int,
            'sector_breakdown': {sector: count},
            'concentration_risk': 'LOW' / 'MEDIUM' / 'HIGH',
            'max_sector': str,
            'max_sector_pct': float,
            'warnings': list of str,
            'recommendation': str,
        }
        """
        all_positions = {}
        for trader in [sentinel.intraday, sentinel.swing, sentinel.longterm]:
            for sym, pos in trader.book.get("positions", {}).items():
                all_positions[sym] = {
                    "strategy": getattr(trader, 'name', '?'),
                    "cost": pos.get("cost", 0),
                    "sector": cls.SECTOR_MAP.get(sym, "Other"),
                }

        if not all_positions:
            return {
                "total_positions": 0,
                "sector_breakdown": {},
                "concentration_risk": "NONE",
                "max_sector": "-",
                "max_sector_pct": 0,
                "warnings": [],
                "recommendation": "No open positions",
            }

        # Sector breakdown
        sector_count = defaultdict(int)
        sector_cost = defaultdict(float)
        total_cost = 0

        for sym, info in all_positions.items():
            sector = info["sector"]
            sector_count[sector] += 1
            sector_cost[sector] += info["cost"]
            total_cost += info["cost"]

        # Find most concentrated sector
        max_sector = max(sector_count, key=sector_count.get)
        max_sector_count = sector_count[max_sector]
        total_pos = len(all_positions)
        max_sector_pct = round(max_sector_count / total_pos * 100, 1) if total_pos > 0 else 0

        # Cost concentration
        max_cost_sector = max(sector_cost, key=sector_cost.get) if sector_cost else "-"
        max_cost_pct = round(sector_cost.get(max_cost_sector, 0) / total_cost * 100, 1) if total_cost > 0 else 0

        # Risk assessment
        warnings = []
        if max_sector_pct > 60:
            concentration_risk = "HIGH"
            warnings.append(
                "{}% of positions in {} — too concentrated! "
                "If {} sector drops, all positions lose.".format(
                    max_sector_pct, max_sector, max_sector))
        elif max_sector_pct > 40:
            concentration_risk = "MEDIUM"
            warnings.append(
                "{}% in {} — consider diversifying.".format(
                    max_sector_pct, max_sector))
        else:
            concentration_risk = "LOW"

        if max_cost_pct > 50:
            warnings.append(
                "{}% of capital in {} sector.".format(
                    max_cost_pct, max_cost_sector))

        if total_pos >= 3 and len(sector_count) == 1:
            warnings.append("ALL positions in same sector — very risky!")
            concentration_risk = "HIGH"

        recommendation = ""
        if concentration_risk == "HIGH":
            other_sectors = [s for s in ["IT", "Pharma", "FMCG", "Banking", "Energy", "Auto"]
                           if s != max_sector]
            recommendation = "Diversify into: {}".format(", ".join(other_sectors[:3]))
        elif concentration_risk == "MEDIUM":
            recommendation = "Watch {} sector exposure".format(max_sector)
        else:
            recommendation = "Portfolio well diversified"

        return {
            "total_positions": total_pos,
            "sector_breakdown": dict(sector_count),
            "sector_cost": {k: round(v, 0) for k, v in sector_cost.items()},
            "concentration_risk": concentration_risk,
            "max_sector": max_sector,
            "max_sector_pct": max_sector_pct,
            "max_cost_pct": max_cost_pct,
            "warnings": warnings,
            "recommendation": recommendation,
        }


# ══════════════════════════════════════════════════════════════
#  4. BACKTEST ENGINE
#     Test any strategy on historical data.
#     Run manually: python3.10 -c "from advanced_trading_engine import BacktestEngine; BacktestEngine.run('RELIANCE', days=200)"
# ══════════════════════════════════════════════════════════════

class BacktestEngine:
    """
    Backtests trading strategies on historical Kite data.
    Run offline — does not affect live trading.
    """

    @staticmethod
    def run(symbol, days=200, strategy="momentum", initial_capital=50000,
            KiteSession=None, send_telegram=None):
        """
        Backtest a strategy on historical data.

        Args:
            symbol: Stock symbol (e.g., 'RELIANCE')
            days: Days of historical data to test
            strategy: 'momentum' or 'mean_reversion'
            initial_capital: Starting capital
            KiteSession: KiteSession class (pass from main script)
            send_telegram: send_telegram function (optional, for results)

        Returns: dict with backtest results
        """
        try:
            import pandas as pd
            import numpy as np

            if not KiteSession:
                logger.error("BacktestEngine needs KiteSession")
                return None

            kite = KiteSession.get()
            if not kite:
                logger.error("Kite not connected for backtest")
                return None

            # Get historical data
            # v23.8.0: DynamicStockUniverse is inline
            token = DynamicStockUniverse.get_token(symbol)
            if not token:
                return None

            from datetime import datetime as dt
            try:
                import pytz
                IST = pytz.timezone("Asia/Kolkata")
                now = dt.now(IST)
            except Exception:
                now = dt.now()

            from_dt = (now - timedelta(days=days)).strftime("%Y-%m-%d")
            to_dt = now.strftime("%Y-%m-%d")
            data = kite.historical_data(token, from_dt, to_dt, "day")

            if not data or len(data) < 50:
                return {"error": "Insufficient data"}

            df = pd.DataFrame(data)
            df.columns = [c.capitalize() for c in df.columns]
            close = df["Close"].values
            high = df["High"].values
            low = df["Low"].values
            # _volume = df["Volume"].values  # noqa

            # Calculate indicators
            # RSI
            delta = np.diff(close, prepend=close[0])
            gain = np.where(delta > 0, delta, 0)
            loss = np.where(delta < 0, -delta, 0)
            avg_gain = pd.Series(gain).rolling(14).mean().values
            avg_loss = pd.Series(loss).rolling(14).mean().values
            rs = avg_gain / (avg_loss + 0.0001)
            rsi = 100 - (100 / (1 + rs))

            # SMA
            sma20 = pd.Series(close).rolling(20).mean().values
            sma50 = pd.Series(close).rolling(50).mean().values

            # MACD
            ema12 = pd.Series(close).ewm(span=12).mean().values
            ema26 = pd.Series(close).ewm(span=26).mean().values
            macd = ema12 - ema26
            macd_signal = pd.Series(macd).ewm(span=9).mean().values

            # ATR
            tr = np.maximum(high - low,
                 np.maximum(np.abs(high - np.roll(close, 1)),
                           np.abs(low - np.roll(close, 1))))
            atr = pd.Series(tr).rolling(14).mean().values

            # ── Run backtest ─────────────────────────────────────
            capital = initial_capital
            position = None
            trades = []
            equity_curve = [capital]

            for i in range(50, len(close)):
                price = close[i]

                if position is None:
                    # Entry logic
                    buy = False
                    if strategy == "momentum":
                        buy = (macd[i] > macd_signal[i] and
                               rsi[i] > 40 and rsi[i] < 70 and
                               close[i] > sma20[i])
                    elif strategy == "mean_reversion":
                        buy = (rsi[i] < 35 and close[i] > sma50[i])

                    if buy and capital > price:
                        qty = max(1, int(capital * 0.1 / price))
                        cost = qty * price
                        sl = price - 1.5 * atr[i]
                        t1 = price + 2.5 * atr[i]
                        position = {
                            "entry_price": price, "qty": qty,
                            "cost": cost, "sl": sl, "t1": t1,
                            "entry_idx": i, "highest": price,
                        }
                        capital -= cost

                else:
                    # Trail SL
                    if price > position["highest"]:
                        position["highest"] = price
                    trail_sl = position["highest"] * 0.9625  # 3.75% trail
                    if trail_sl > position["sl"]:
                        position["sl"] = trail_sl

                    # Exit logic
                    exit_reason = None
                    if price <= position["sl"]:
                        exit_reason = "SL"
                    elif price >= position["t1"]:
                        exit_reason = "TARGET"
                    elif i - position["entry_idx"] >= 28:
                        exit_reason = "TIME"

                    if exit_reason:
                        pnl = (price - position["entry_price"]) * position["qty"]
                        capital += position["cost"] + pnl
                        trades.append({
                            "entry": position["entry_price"],
                            "exit": price,
                            "pnl": round(pnl, 2),
                            "reason": exit_reason,
                            "days": i - position["entry_idx"],
                        })
                        position = None

                equity_curve.append(capital + (
                    position["qty"] * price - position["cost"] if position else 0))

            # ── Results ──────────────────────────────────────────
            wins = [t for t in trades if t["pnl"] > 0]
            losses = [t for t in trades if t["pnl"] <= 0]
            total_pnl = sum(t["pnl"] for t in trades)
            win_rate = len(wins) / len(trades) * 100 if trades else 0
            avg_win = sum(t["pnl"] for t in wins) / len(wins) if wins else 0
            avg_loss = sum(t["pnl"] for t in losses) / len(losses) if losses else 0

            # Max drawdown
            peak = initial_capital
            max_dd = 0
            for eq in equity_curve:
                if eq > peak:
                    peak = eq
                dd = (peak - eq) / peak * 100
                if dd > max_dd:
                    max_dd = dd

            result = {
                "symbol": symbol,
                "strategy": strategy,
                "days": days,
                "initial_capital": initial_capital,
                "final_capital": round(capital, 2),
                "total_pnl": round(total_pnl, 2),
                "return_pct": round(total_pnl / initial_capital * 100, 2),
                "total_trades": len(trades),
                "wins": len(wins),
                "losses": len(losses),
                "win_rate": round(win_rate, 1),
                "avg_win": round(avg_win, 2),
                "avg_loss": round(avg_loss, 2),
                "max_drawdown_pct": round(max_dd, 2),
                "rr_ratio": round(abs(avg_win / avg_loss), 2) if avg_loss else 0,
                "trades": trades[-10:],  # Last 10 trades
            }

            logger.info(
                "BACKTEST [{}] {}: {} trades, {:.1f}% win rate, "
                "PnL: ₹{:,.0f} ({:.1f}%), Max DD: {:.1f}%".format(
                    symbol, strategy, len(trades), win_rate,
                    total_pnl, result["return_pct"], max_dd))

            if send_telegram:
                send_telegram(
                    "\U0001F4CA *BACKTEST RESULT — {} ({})*\n".format(
                        symbol, strategy)
                    + "\u2501" * 30 + "\n"
                    + "Period: {} days\n".format(days)
                    + "Trades: {} (W:{} L:{})\n".format(
                        len(trades), len(wins), len(losses))
                    + "Win Rate: {:.1f}%\n".format(win_rate)
                    + "P&L: \u20b9{:,.0f} ({:.1f}%)\n".format(
                        total_pnl, result["return_pct"])
                    + "Max Drawdown: {:.1f}%\n".format(max_dd)
                    + "R:R Ratio: {:.2f}\n".format(result["rr_ratio"])
                    + "\u2501" * 30 + "\n"
                    + "\U0001F4CC {} strategy on {} historical data".format(
                        strategy, symbol),
                    priority="report"
                )

            return result

        except Exception as e:
            logger.error("Backtest error: {}".format(e))
            return {"error": str(e)}



class DynamicStockUniverse:
    """
    Loads ALL NSE equity stocks from Kite instruments API.
    Auto-filters: removes SME, commodities, ETFs, bonds, low-price stocks.
    Auto-deduplicates: NSE preferred over BSE.
    Result: 1000-1500 valid, tradeable stocks. Updated daily.
    """

    # Segments to EXCLUDE
    EXCLUDED_SEGMENTS = {"SME", "SME-EMERGE", "BE", "BZ", "GS", "MF", "IF"}
    # Instrument types to EXCLUDE
    EXCLUDED_TYPES    = {"COMMODITY", "CURRENCY", "CE", "PE", "FUT"}
    # Name patterns to EXCLUDE (commodities, ETFs, bonds)
    EXCLUDED_PATTERNS = [
        "ETF", "GOLD", "SILVER", "CRUDE", "NIFTY", "SENSEX",
        "LIQUID", "BOND", "GILT", "MONEY", "OVERNIGHT",
        "DEBT", "SOVEREIGN", "CPSE", "BHARAT", "GROWTH",
        "-SG", "-GR", "-DP", "-IV", "BEES",
        "GOLDBEES", "SILVERBEES", "LIQUIDBEES",
        # FIX #9: Government securities, bonds, debentures
        "GS20", "GS19", "GSEC", "AFIL", "SSCL", "SDL",
        "TBILL", "SGBOND", "FLOATING", "NCDS", "NCD",
        # v25.5.5: Bond/NCD patterns that show as circuit stocks
        "IIFLZC", "SCLZC", "AEL17", "AEL18", "AEL19", "AEL20",
        "IRFCZC", "PNBZC", "SBIZC", "HDFCZC", "ABORLZC", "TABORLZC",
    ]
    # Indices — scan but don't trade
    INDICES = {"NIFTY", "BANKNIFTY", "FINNIFTY", "MIDCPNIFTY"}

    _cache = []
    _cache_date = ""
    _all_instruments = {}  # symbol → instrument_token mapping

    @classmethod
    def load(cls, kite):
        """
        Load full stock universe from Kite instruments API.
        Called once per day at startup or first scan.
        Returns list of tradeable symbols (1000+).
        """
        global PRIORITY_500

        today = now_ist().strftime("%Y-%m-%d")
        if cls._cache and cls._cache_date == today:
            return cls._cache

        if not kite:
            logger.warning("Kite not available — using fallback FNO list")
            return list(FNO_STOCKS)

        try:
            logger.info("📡 Loading stock universe from Kite instruments API...")
            instruments = kite.instruments("NSE")
            logger.info(f"  Kite returned {len(instruments)} NSE instruments")

            # Build token cache for ALL instruments
            cls._all_instruments = {}
            valid_stocks = []

            for inst in instruments:
                sym      = inst.get("tradingsymbol", "")
                name     = inst.get("name", "").upper()
                segment  = inst.get("segment", "").upper()
                inst_type= inst.get("instrument_type", "").upper()
                # _exchange = inst.get("exchange", "").upper()  # noqa
                token    = inst.get("instrument_token", 0)

                # Store ALL tokens for historical data
                if sym and token:
                    cls._all_instruments[sym] = token

                # ── FILTER: Only equity stocks ──
                # Must be EQ (equity) instrument type
                if inst_type not in ("EQ", ""):
                    continue

                # Skip if segment is excluded (SME, bonds, etc)
                if any(seg in segment for seg in cls.EXCLUDED_SEGMENTS):
                    continue

                # Skip if name contains excluded patterns
                if any(pat in name or pat in sym for pat in cls.EXCLUDED_PATTERNS):
                    continue

                # Skip empty or numeric-only symbols
                if not sym or sym.isdigit() or len(sym) < 2:
                    continue

                # FIX #9: Skip government securities (start with digits)
                # e.g., 591GS2028-GS, 12AFIL27-N0, 99SSCL2035-N4, 79ABCL35-N1
                if sym[0].isdigit():
                    continue
                # Skip symbols with hyphens followed by letter+digit (bond series)
                if "-" in sym and any(c.isdigit() for c in sym.split("-")[-1]):
                    continue

                # Skip if symbol has SME markers
                if any(m in sym for m in ["-SM", "-BE", "-BZ", "-IL", "-BL"]):
                    continue

                valid_stocks.append(sym)

            # Add indices for scanning (not trading)
            for idx in cls.INDICES:
                if idx not in valid_stocks:
                    valid_stocks.append(idx)

            # Ensure all F&O stocks are included
            for fno_sym in FNO_STOCKS:
                if fno_sym not in valid_stocks:
                    valid_stocks.append(fno_sym)

            # Deduplicate
            valid_stocks = list(dict.fromkeys(valid_stocks))

            cls._cache = valid_stocks
            cls._cache_date = today

            # Update global PRIORITY_500
            PRIORITY_500 = valid_stocks

            # Save to file for debugging
            save_json(INSTRUMENTS_FILE, {
                "date": today,
                "count": len(valid_stocks),
                "stocks": valid_stocks[:50],  # First 50 for debug
                "total_instruments": len(instruments),
                "token_cache_size": len(cls._all_instruments),
            })

            logger.info(f"✅ Stock Universe: {len(valid_stocks)} tradeable stocks loaded")
            logger.info(f"  Token cache: {len(cls._all_instruments)} instruments")
            return valid_stocks

        except Exception as e:
            logger.error(f"Stock universe load failed: {e}")
            # Fallback to F&O list
            cls._cache = list(FNO_STOCKS)
            return cls._cache

    @classmethod
    def get_token(cls, symbol):
        """Get instrument token for a symbol. Used by scanner."""
        # Hardcoded index tokens
        index_tokens = {
            "NIFTY":      256265,
            "BANKNIFTY":  260105,
            "FINNIFTY":   257801,
            "MIDCPNIFTY": 288009,
        }
        if symbol in index_tokens:
            return index_tokens[symbol]
        return cls._all_instruments.get(symbol)

    @classmethod
    def is_fno(cls, symbol):
        """Check if a symbol is F&O eligible."""
        return symbol in FNO_STOCKS

# ─── Logging ──────────────────────────────────────────────────────────────────
class NullByteFilter(logging.Filter):
    """Strip null bytes from log messages to prevent binary file corruption."""
    def filter(self, record):
        if record.msg and isinstance(record.msg, str):
            record.msg = record.msg.replace('\x00', '')
        if record.args:
            cleaned = []
            for a in record.args if isinstance(record.args, (list, tuple)) else [record.args]:
                if isinstance(a, str):
                    cleaned.append(a.replace('\x00', ''))
                else:
                    cleaned.append(a)
            record.args = tuple(cleaned) if isinstance(record.args, tuple) else cleaned
        return True

