    _alerted_catalysts = {}

    @classmethod
    def scan_news(cls, news_alerts):
        """Scan recent news for sector catalysts. Returns signals list."""
        signals = []
        today = now_ist().strftime("%Y-%m-%d")
        for alert in news_alerts:
            text = (alert.get("title", "") + " " + alert.get("summary", "")).lower()
            for cat_name, cat_def in cls.SECTOR_CATALYSTS.items():
                matched = [kw for kw in cat_def["trigger_keywords"] if kw in text]
                if not matched:
                    continue
                _dedup_key = f"{cat_name}_{today}"
                if _dedup_key in cls._alerted_catalysts:
                    continue
                cls._alerted_catalysts[_dedup_key] = today
                cls._alerted_catalysts = {k: v for k, v in cls._alerted_catalysts.items()
                    if v >= (now_ist() - timedelta(days=3)).strftime("%Y-%m-%d")}
                logger.info(f"\U0001f3af SECTOR CATALYST [{cat_name}]: {matched[0]}")
                for sym in cat_def["beneficiaries"]:
                    signals.append({"symbol": sym, "direction": "BUY",
                        "source": f"CATALYST|{cat_name}", "catalyst": cat_name,
                        "sector_names": cat_def["sector_names"], "tier": 2,
                        "max_entry_pct_from_high": cat_def.get("max_entry_pct_from_high", 20),
                        "description": cat_def["description"]})
                for sn in cat_def.get("sector_names", []):
                    signals.append({"symbol": f"__SECTOR__{sn}", "direction": "BUY",
                        "source": f"CATALYST|{cat_name}|SECTOR", "catalyst": cat_name,
                        "sector_name": sn, "tier": 1,
                        "max_entry_pct_from_high": cat_def.get("max_entry_pct_from_high", 20),
                        "description": cat_def["description"]})
                _bene = ", ".join(cat_def["beneficiaries"][:8])
                _sect = ", ".join(cat_def["sector_names"][:3])
                send_telegram(
                    f"\U0001f3af *SECTOR CATALYST*\n"
                    f"\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\n"
                    f"Type: {cat_name.replace('_', ' ')}\n"
                    f"Trigger: {matched[0]}\n"
                    f"Sector: {_sect}\n"
                    f"Top picks: `{_bene}`\n"
                    f"_{cat_def['description']}_\n"
                    f"\n\u26a0\ufe0f Entry only near support — full 12-step pipeline",
                    priority="trade")
        return signals

    @classmethod
    def filter_by_price_level(cls, signals, scans):
        """Filter signals — only keep stocks near support."""
        actionable = []
        for sig in signals:
            if sig["symbol"].startswith("__SECTOR__"):
                actionable.append(sig)
                continue
            sym = sig["symbol"]
            scan = next((r for r in scans if r["symbol"] == sym), None)
            if not scan:
                continue
            price = scan.get("price", 0)
            w52_high = scan.get("w52_high", 0)
            if price <= 0 or w52_high <= 0:
                continue
            pct_from_high = ((w52_high - price) / w52_high) * 100
            max_pct = sig.get("max_entry_pct_from_high", 20)
            if pct_from_high < max_pct:
                sig["wait_for_pullback"] = True
                logger.info(f"\U0001f3af CATALYST SKIP [{sym}]: {pct_from_high:.1f}% from high (need >{max_pct}%)")
            else:
                sig["wait_for_pullback"] = False
                sig["price"] = price
                sig["pct_from_high"] = round(pct_from_high, 1)
            actionable.append(sig)
        return actionable

    @classmethod
    def get_sector_boost(cls, symbol, scan_result, catalyst_watchlist):
        """Returns (boost, catalyst_name) for DVM adjustment.
        Tier 2 (+5): named beneficiary in buy zone. Tier 1 (+3): sector match."""
        if not catalyst_watchlist:
            return 0, ""
        if symbol in catalyst_watchlist:
            info = catalyst_watchlist[symbol]
            if info.get("wait_for_pullback"):
                return 0, ""
            return 5, info.get("catalyst", "CATALYST")
        _stock_sector = (scan_result.get("sector", "") or scan_result.get("industry", "") or "").upper()
        if not _stock_sector:
            return 0, ""
        for key, info in catalyst_watchlist.items():
            if key.startswith("__SECTOR__"):
                _cat_sector = key.replace("__SECTOR__", "").upper()
                if (_cat_sector in _stock_sector or _stock_sector in _cat_sector
                        or any(w in _stock_sector for w in _cat_sector.split() if len(w) > 3)):
                    if not info.get("wait_for_pullback"):
                        return 3, info.get("catalyst", "SECTOR_CATALYST")
        return 0, ""


