    def _estimate_result_date(self, symbol, quarter_end_month=3):
        """
        Estimate result date for any F&O stock based on historical week pattern.
        Quarter end March 2026 → results in April/May 2026.
        """
        week = self.RESULT_WEEK_PATTERN.get(symbol, 5)  # Default week 5 (late April)
        # Week 1-4 = same month after quarter end (April for Q4)
        # Week 5-8 = next month (May for Q4)
        base_month = quarter_end_month + 1  # April for Q4 (March end)
        if week > 4:
            base_month += 1
            week -= 4
        base_year = 2026
        if base_month > 12:
            base_month -= 12
            base_year += 1
        day = min(7 * week, 28)
        try:
            return datetime(base_year, base_month, day).strftime("%Y-%m-%d")
        except:
            return f"{base_year}-{base_month:02d}-{min(day, 28):02d}"

    def early_bird_scan(self, news_items=None, fno_symbols=None):
        """
        PROACTIVE F&O scanner. Scans ALL F&O stocks, scores based on
        calendar proximity + news signals. Returns ranked opportunities.
        
        Called at EOD daily. Also triggered when high-impact news arrives.
        """
        today = now_ist().date()
        plays = []
        
        # Get all F&O symbols from Kite instruments (or use cached list)
        symbols_to_scan = list(self.RESULT_WEEK_PATTERN.keys())
        if fno_symbols:
            symbols_to_scan = list(set(symbols_to_scan + fno_symbols))
        
        # Build news text corpus for signal matching
        news_corpus = {}  # {symbol_lower: [texts]}
        if news_items:
            for item in news_items:
                text = (str(item.get("title", "")) + " " + str(item.get("desc", ""))).lower()
                for sym in symbols_to_scan:
                    if sym.lower() in text:
                        if sym not in news_corpus:
                            news_corpus[sym] = []
                        news_corpus[sym].append(text)
        
        for symbol in symbols_to_scan:
            try:
                # Check calendar
                cal = self.data.get("earnings_calendar", {}).get(symbol, {})
                if cal.get("result_date"):
                    est_date_str = cal["result_date"]
                    confirmed = cal.get("confirmed", False)
                else:
                    est_date_str = self._estimate_result_date(symbol)
                    confirmed = False
                
                est_date = datetime.strptime(est_date_str, "%Y-%m-%d").date()
                days_until = (est_date - today).days
                
                if days_until < 0 or days_until > 45:
                    continue
                
                score = 0
                signals = []
                direction = "BULLISH"
                
                # ── Calendar proximity ──
                if 14 <= days_until <= 28:
                    score += 15
                    signals.append(f"SWEET_SPOT:{days_until}d")
                elif 28 < days_until <= 45:
                    score += 5
                    signals.append(f"SCOUT:{days_until}d")
                elif 7 <= days_until < 14:
                    score += 8
                    signals.append(f"IV_RISING:{days_until}d")
                
                if confirmed:
                    score += 10
                    signals.append("CONFIRMED")
                
                # ── News signal scoring ──
                sym_news = news_corpus.get(symbol, [])
                bull_hits = 0
                bear_hits = 0
                for text in sym_news:
                    for kw in self.EARLY_BIRD_BULLISH:
                        if kw in text:
                            bull_hits += 1
                    for kw in self.EARLY_BIRD_BEARISH:
                        if kw in text:
                            bear_hits += 1
                
                if bull_hits >= 4:
                    score += 20; signals.append(f"STRONG_BULL_NEWS:{bull_hits}")
                elif bull_hits >= 2:
                    score += 10; signals.append(f"BULL_NEWS:{bull_hits}")
                
                if bear_hits >= 3:
                    score -= 15; direction = "BEARISH"
                    signals.append(f"BEAR_NEWS:{bear_hits}")
                elif bear_hits >= 1:
                    score -= 5; signals.append(f"CAUTION:{bear_hits}")
                
                # ── Existing conviction data ──
                existing = self.data.get("conviction_scores", {}).get(symbol, {})
                if existing.get("score", 0) >= 70:
                    score += 10
                    signals.append(f"PRIOR_HIGH:{existing['score']}")
                
                score = max(0, min(100, score))
                
                # Determine action
                if 14 <= days_until <= 28 and score >= 65:
                    action = "ENTER"
                elif days_until > 28 and score >= 70:
                    action = "WATCH"
                elif 7 <= days_until < 14 and score >= 75:
                    action = "LATE"
                else:
                    action = "MONITOR"
                
                if score >= 40:  # Only include stocks with some signal
                    plays.append({
                        "symbol": symbol, "est_date": est_date_str,
                        "confirmed": confirmed, "days_until": days_until,
                        "score": score, "direction": direction,
                        "signals": signals, "action": action,
                    })
            except Exception as e:
                logger.debug(f"Early bird [{symbol}]: {e}")
        
        plays.sort(key=lambda x: (-x["score"], x["days_until"]))
        return plays

    def early_bird_auto_enter(self, plays, fno_adapter):
        """Auto-enter F&O positions for ENTER-phase plays with score >= 65."""
        entered = []
        for play in plays:
            if play["action"] != "ENTER" or play["score"] < 65:
                continue
            symbol = play["symbol"]
            # Check if already positioned
            fno_book = fno_adapter.fno.book if hasattr(fno_adapter, 'fno') else fno_adapter.book
            existing = any(pos.get("symbol") == symbol
                          for pos in fno_book.get("positions", {}).values())
            if existing:
                continue
            # Get spot price
            try:
                kite = KiteSession.get()
                if not kite:
                    continue
                ltp = kite.ltp([f"NSE:{symbol}"])
                spot = ltp.get(f"NSE:{symbol}", {}).get("last_price", 0)
                if spot <= 0:
                    continue
            except:
                continue
            # Enter
            try:
                conf = "STRONG_BULLISH" if play["score"] >= 80 else "BULLISH"
                result = fno_adapter.enter(
                    symbol, spot, play["direction"],
                    source=f"EARLY_BIRD_T-{play['days_until']}",
                    confidence=conf
                )
                if result:
                    entered.append(play)
                    logger.info(f"🦅 EARLY BIRD ENTRY: {symbol} {play['direction']} "
                                f"Score:{play['score']} DTE:{play['days_until']}")
            except Exception as e:
                logger.error(f"Early bird entry [{symbol}]: {e}")
        
        if entered:
            lines = "\n".join(
                f"  {e['symbol']} {e['direction']} | Score:{e['score']} | "
                f"Results:{e['est_date']} ({e['days_until']}d)"
                for e in entered)
            send_telegram(
                f"🦅 *EARLY BIRD — {len(entered)} F&O ENTRIES*\n"
                f"{lines}", priority="trade")
        return entered

    def early_bird_report(self, plays=None, fno_symbols=None):
        """Send Telegram Early Bird scouting report."""
        if plays is None:
            plays = self.early_bird_scan(fno_symbols=fno_symbols)
        if not plays:
            return
        
        enter = [p for p in plays if p["action"] == "ENTER"]
        watch = [p for p in plays if p["action"] == "WATCH"]
        late = [p for p in plays if p["action"] == "LATE"]
        
        lines = []
        if enter:
            lines.append("🟢 *ENTER NOW (14-28d, ≥65):*")
            for p in enter[:6]:
                lines.append(f"  {p['symbol']} {p['direction']} {p['score']}/100 | {p['est_date']} ({p['days_until']}d)")
        if watch:
            lines.append("🟡 *WATCHLIST (>28d, ≥70):*")
            for p in watch[:5]:
                lines.append(f"  {p['symbol']} {p['score']}/100 | {p['est_date']} ({p['days_until']}d)")
        if late:
            lines.append("🟠 *LATE (<14d, ≥75):*")
            for p in late[:3]:
                lines.append(f"  {p['symbol']} {p['score']}/100 | {p['est_date']} ({p['days_until']}d)")
        
        msg = (
            "🦅 *EARLY BIRD F&O SCANNER*\n"
            f"Tracked: {len(plays)} | Enter: {len(enter)} | Watch: {len(watch)}\n"
            + "\n".join(lines)
        )
        send_telegram(msg, priority="normal")
        return plays

