# ═══════════════════════════════════════════════════════════════════════════════
#  GIR DUAL-BRAIN ARCHITECTURE
#  Two independent brains. Zero shared candidates. Zero shared filters.
# ═══════════════════════════════════════════════════════════════════════════════

class EquityBrain:
    """
    GIR Equity Brain — independent equity decision engine.
    
    Owns:
      - UnifiedTrader / LiveEquityTrader
      - 3-Agent AI voting (with SIDEWAYS regime filter)
      - DVM scoring + Pod system
      - GTT management + Trailing SL
      - Kelly position sizing
      - Dead money exits (15-day)
      - Sector rotation scoring
      - All equity scanners (Penny, 52-week, Promoter, etc.)
    
    Does NOT touch F&O. Has its own candidate pool.
    """
    
    def __init__(self, sentinel):
        self.sentinel = sentinel
        self.trader = sentinel.equity  # UnifiedTrader or LiveEquityTrader
        self.three_ai = sentinel.three_ai
        self.macro = sentinel.macro
        self.patterns = sentinel.patterns
        self.sentiment = sentinel.sentiment
        self.earnings = sentinel.earnings
        self.stat_arb = sentinel.stat_arb
        self.amo = sentinel.amo
        self.risk = sentinel.risk
        self._equity_queue = []
        logger.info("🧠 EQUITY BRAIN initialized — regime filters ACTIVE")
    
    def scan_and_queue(self, scans):
        """
        Phase 1: Scan equity universe → build equity-only queue.
        Uses 3-Agent AI, DVM, pod system, regime filters.
        """
        self._equity_queue = []
        if not scans:
            return
        _scan_iter = scans.items() if isinstance(scans, dict) else (
            (d.get("symbol", ""), d) for d in scans if isinstance(d, dict)
        )
        for symbol, data in _scan_iter:
            if not isinstance(data, dict):
                continue
            # Skip F&O-only symbols that shouldn't be in equity
            confidence = data.get("confidence", 0)
            dvm = data.get("dvm_score", 0)
            pod = get_pod_for_sector(symbol)
            pod_name = [k for k, v in GRIFFIN_POD_CONFIG.items() if v == pod]
            pod_name = pod_name[0] if pod_name else "SERVICES"
            pod_conf_min = pod.get("confidence_min", 45)
            pod_dvm_min = pod.get("dvm_min", 60)
            
            if confidence >= pod_conf_min and dvm >= pod_dvm_min:
                self._equity_queue.append({
                    "symbol": symbol,
                    "engine": "EQUITY",
                    "confidence": confidence,
                    "dvm": dvm,
                    "pod": pod_name,
                    "ltp": data.get("ltp", 0),
                    "atr": data.get("atr", 0),
                    "sl_atr_mult": pod.get("sl_atr_mult", 2.0),
                    "t2_atr_mult": pod.get("t2_atr_mult", 12.0),
                    "data": data,
                })
        logger.info(f"🧠 EQUITY BRAIN: {len(self._equity_queue)} candidates queued")
        return self._equity_queue
    
    def get_queue(self):
        return self._equity_queue


class FnoBrain:
    """
    GIR F&O Brain — independent F&O decision engine.
    
    Owns:
      - FNOTrader / LiveFNOAdapter
      - FNOIntelEngine (24/7 intelligence)
      - MoonshotScanner (deep OTM lottery tickets)
      - FNOExitEngine (18 exit rules)
      - Index Options Scanner (NIFTY/BANKNIFTY)
      - Independent F&O scanning (momentum, oversold, overbought)
      - Three-phase cycle: evening AMO → morning scan → market hours
    
    CRITICAL: NO SIDEWAYS REGIME FILTER.
    F&O is direction-agnostic — strong move = opportunity (CE or PE).
    Has its own candidate pool, completely separate from equity.
    """
    
    FNO_PHASES = {
        "EVENING_AMO":   (15, 30, 23, 59),  # 15:30 - 23:59 — place AMO for next day
        "MORNING_SCAN":  (6, 0, 9, 14),     # 06:00 - 09:14 — pre-market analysis
        "MARKET_HOURS":  (9, 15, 15, 29),    # 09:15 - 15:29 — active trading
    }
    
    def __init__(self, sentinel):
        self.sentinel = sentinel
        self.trader = sentinel.fno  # FNOTrader or LiveFNOAdapter
        self.intel = getattr(sentinel, '_fno_intel', None)
        self.moonshot = getattr(sentinel, '_moonshot', None)
        self.exit_engine = getattr(sentinel, '_exit_engine', None)
        self._fno_queue = []
        self._phase = "IDLE"
        logger.info("🧠 F&O BRAIN initialized — NO regime filter, 3-phase cycle")
    
    def get_current_phase(self):
        """Determine current F&O phase based on IST time."""
        n = now_ist()
        hr, mn = n.hour, n.minute
        t = hr * 100 + mn
        
        if 1530 <= t <= 2359:
            return "EVENING_AMO"
        elif 600 <= t <= 914:
            return "MORNING_SCAN"
        elif 915 <= t <= 1529:
            return "MARKET_HOURS"
        else:
            return "IDLE"
    
    def scan_and_queue(self, scans, kite=None):
        """
        Independent F&O scanning — NO equity regime filters applied.
        Scans F&O universe for momentum, oversold bounces, overbought shorts.
        Also runs index options scanner and moonshot scanner.
        """
        self._fno_queue = []
        
        if not kite:
            kite = KiteSession.get()
        if not kite:
            logger.warning("F&O BRAIN: No Kite connection — skipping scan")
            return self._fno_queue
        
        # ── Stock F&O: Independent momentum/technical scan ──
        if scans:
            _scan_list = scans if isinstance(scans, list) else [scans[k] for k in scans]
            _fno_scanned = 0
            for _sd in _scan_list:
                if not isinstance(_sd, dict): continue
                _sym = _sd.get("symbol", "")
                if _sym not in FNO_STOCKS: continue
                _fno_scanned += 1
                _day_chg = _sd.get("day_change_pct", 0)
                _vol_ratio = _sd.get("volume_ratio", 0)
                _rsi = _sd.get("rsi", 50)
                _dvm = _sd.get("dvm_score", 0)
                _direction = None; _score = 0; _reason = ""
                
                # Strong momentum up
                if _day_chg >= 0.8 and _vol_ratio >= 0.8:
                    _direction = "BULLISH"; _score = 70 + min(_day_chg * 5, 30)
                    _reason = f"STRONG UP {_day_chg:+.1f}% Vol:{_vol_ratio:.1f}x"
                # Strong momentum down
                elif _day_chg <= -0.8 and _vol_ratio >= 0.8:
                    _direction = "BEARISH"; _score = 70 + min(abs(_day_chg) * 5, 30)
                    _reason = f"STRONG DOWN {_day_chg:+.1f}% Vol:{_vol_ratio:.1f}x"
                # Oversold bounce
                elif _rsi < 40 and _dvm >= 50:
                    _direction = "BULLISH"; _score = 65
                    _reason = f"OVERSOLD RSI:{_rsi:.0f} DVM:{_dvm}"
                # Overbought reversal
                elif _rsi > 65 and _day_chg <= -0.5:
                    _direction = "BEARISH"; _score = 65
                    _reason = f"OVERBOUGHT RSI:{_rsi:.0f} Chg:{_day_chg:+.1f}%"
                # DVM momentum
                elif _dvm >= 60 and abs(_day_chg) >= 0.5:
                    _direction = "BULLISH" if _day_chg > 0 else "BEARISH"
                    _score = 60 + _dvm * 0.2
                    _reason = f"MOMENTUM DVM:{_dvm} Chg:{_day_chg:+.1f}%"
                
                if _direction and _score >= 60:
                    self._fno_queue.append({
                        "symbol": _sym, "engine": "SAFE_FNO", "score": _score,
                        "catalyst": _reason, "direction": _direction, "data": _sd
                    })
            logger.info(f"🧠 F&O BRAIN STOCK SCAN: {_fno_scanned} checked, {len(self._fno_queue)} qualified")
        
        # ── Index Options: NIFTY/BANKNIFTY ──
        self._scan_index_options(scans, kite)
        
        # ── FNOIntelEngine proposals ──
        if self.intel:
            try:
                signals = self.intel.get_signals()
                if signals:
                    for sig in signals:
                        if sig.get("score", 0) >= 60:
                            self._fno_queue.append({
                                "symbol": sig["symbol"],
                                "engine": "SAFE_FNO",
                                "score": sig["score"],
                                "catalyst": sig.get("catalyst", "INTEL"),
                                "direction": sig.get("direction", "BULLISH"),
                                "data": sig,
                            })
            except Exception as e:
                logger.debug(f"F&O Brain intel signals: {e}")
        
        # ── GIR: NEWS-DRIVEN F&O — reads news, decides CE or PE ──
        # IntelligenceDecisionEngine already analyzes 39 feeds + 320 keywords
        # This wires confirmed BULLISH/BEARISH news directly to F&O orders
        try:
            _intel_engine = None
            if hasattr(self.sentinel, '_intel_engine') and self.sentinel._intel_engine:
                _intel_engine = self.sentinel._intel_engine
            elif hasattr(self.sentinel, 'brokerage_monitor') and self.sentinel.brokerage_monitor:
                _intel_engine = getattr(self.sentinel.brokerage_monitor, '_intel_engine', None)
            
            if _intel_engine and hasattr(_intel_engine, 'candidates') and _intel_engine.candidates:
                _news_fno_added = 0
                for _cand in _intel_engine.candidates[-20:]:  # Last 20 candidates
                    _sym = _cand.get("symbol", "")
                    if _sym not in FNO_STOCKS:
                        continue
                    _direction = _cand.get("direction", "")
                    _score = _cand.get("score", 0)
                    _catalyst = _cand.get("catalyst", _cand.get("reason", "NEWS"))
                    _sentiment = _cand.get("sentiment", "")
                    
                    # Strong BULLISH news → CE
                    if _direction == "BULLISH" and _score >= 60:
                        self._fno_queue.append({
                            "symbol": _sym, "engine": "NEWS_CE",
                            "score": _score, "catalyst": f"NEWS_BULL: {_catalyst[:60]}",
                            "direction": "BULLISH", "data": _cand,
                        })
                        _news_fno_added += 1
                    # Strong BEARISH news → PE
                    elif _direction == "BEARISH" and _score >= 60:
                        self._fno_queue.append({
                            "symbol": _sym, "engine": "NEWS_PE",
                            "score": _score, "catalyst": f"NEWS_BEAR: {_catalyst[:60]}",
                            "direction": "BEARISH", "data": _cand,
                        })
                        _news_fno_added += 1
                
                if _news_fno_added > 0:
                    logger.info(f"📰 F&O BRAIN NEWS: {_news_fno_added} news-driven candidates (CE+PE) from IntelEngine")
            
            # Also check BrokerageMonitor direct hits for F&O-eligible stocks
            if hasattr(self.sentinel, 'brokerage_monitor') and self.sentinel.brokerage_monitor:
                _bm = self.sentinel.brokerage_monitor
                _bm_candidates = getattr(_bm, 'candidates', [])
                _news_bm_added = 0
                for _bc in _bm_candidates[-15:]:
                    _sym = _bc.get("symbol", "")
                    if _sym not in FNO_STOCKS:
                        continue
                    _title = _bc.get("title", "").lower()
                    _kws = _bc.get("keywords", [])
                    
                    # Check for bearish keywords → PE
                    _bearish_kws = {"sell", "downgrade", "reduce", "underperform", "target cut",
                                    "fraud", "loss", "penalty", "crash", "decline", "weak"}
                    _bullish_kws = {"buy", "upgrade", "outperform", "target raised", "order win",
                                    "record", "beat", "strong", "growth", "expansion"}
                    
                    _is_bear = any(bk in _title for bk in _bearish_kws)
                    _is_bull = any(bk in _title for bk in _bullish_kws)
                    
                    if _is_bear and not _is_bull:
                        self._fno_queue.append({
                            "symbol": _sym, "engine": "BROKERAGE_PE",
                            "score": 65, "catalyst": f"BROKERAGE_BEAR: {_title[:60]}",
                            "direction": "BEARISH", "data": _bc,
                        })
                        _news_bm_added += 1
                    elif _is_bull and not _is_bear:
                        self._fno_queue.append({
                            "symbol": _sym, "engine": "BROKERAGE_CE",
                            "score": 65, "catalyst": f"BROKERAGE_BULL: {_title[:60]}",
                            "direction": "BULLISH", "data": _bc,
                        })
                        _news_bm_added += 1
                
                if _news_bm_added > 0:
                    logger.info(f"📰 F&O BRAIN BROKERAGE: {_news_bm_added} brokerage-driven candidates from {len(_bm_candidates)} hits")
        except Exception as _news_fno_err:
            logger.debug(f"F&O Brain news scan: {_news_fno_err}")

        # ── GIR: Early Bird catalyst scan — runs every cycle, not just EOD ──
        if self.intel and hasattr(self.intel, 'early_bird_scan'):
            try:
                _eb_news = []
                _sentinel = self.sentinel
                if hasattr(_sentinel, '_brokerage_monitor') and _sentinel._brokerage_monitor:
                    for _fn, _items in getattr(_sentinel._brokerage_monitor, '_last_parsed', {}).items():
                        if isinstance(_items, list):
                            _eb_news.extend(_items)
                if hasattr(_sentinel, '_news_cache'):
                    for _nc_name, _nc_items in (_sentinel._news_cache or {}).items():
                        if isinstance(_nc_items, list):
                            _eb_news.extend(_nc_items)
                _fno_syms = list(FNO_STOCKS)
                _eb_plays = self.intel.early_bird_scan(news_items=_eb_news, fno_symbols=_fno_syms)
                if _eb_plays:
                    _enter_plays = [p for p in _eb_plays if p.get("action") == "ENTER"]
                    for _ep in _enter_plays[:3]:
                        self._fno_queue.append({
                            "symbol": _ep.get("symbol", ""),
                            "engine": "CATALYST",
                            "score": _ep.get("score", 50),
                            "catalyst": "|".join(_ep.get("signals", [])),
                            "direction": _ep.get("direction", "BULLISH"),
                            "data": _ep,
                        })
                    logger.info(f"🐦 F&O BRAIN EARLY BIRD: {len(_eb_plays)} tracked, {len(_enter_plays)} ready to enter")
            except Exception as _eb_err:
                logger.debug(f"F&O Brain early bird: {_eb_err}")

        # ── Moonshot proposals ──
        if self.moonshot:
            try:
                moon_candidates = self.moonshot.scan(kite=kite)
                if moon_candidates:
                    for mc in moon_candidates:
                        self._fno_queue.append({
                            "symbol": mc.get("symbol", ""),
                            "engine": "FNO_MOONSHOT",
                            "score": mc.get("score", 50),
                            "catalyst": mc.get("catalyst", "MOONSHOT"),
                            "direction": mc.get("direction", "BULLISH"),
                            "data": mc,
                        })
            except Exception as e:
                logger.debug(f"F&O Brain moonshot: {e}")
        
        logger.info(f"🧠 F&O BRAIN TOTAL: {len(self._fno_queue)} candidates queued")
        return self._fno_queue
    
    def _scan_index_options(self, scans, kite):
        """Scan NIFTY/BANKNIFTY for index options plays."""
        if not kite:
            return
        try:
            _idx_quotes = kite.ltp(["NSE:NIFTY 50", "NSE:NIFTY BANK", "NSE:INDIA VIX"])
            _nifty_spot = _idx_quotes.get("NSE:NIFTY 50", {}).get("last_price", 0)
            _bnf_spot = _idx_quotes.get("NSE:NIFTY BANK", {}).get("last_price", 0)
            _vix = _idx_quotes.get("NSE:INDIA VIX", {}).get("last_price", 0)
            _vix_regime = _get_vix_regime(_vix) if _vix > 0 else "UNKNOWN"
            
            if _nifty_spot <= 0:
                return
            
            _idx_score = 0
            _idx_reasons = []
            
            # VIX factor
            if _vix_regime in ("EXTREME_FEAR", "FEAR"):
                _idx_score += 2; _idx_reasons.append(f"VIX={_vix:.1f}({_vix_regime})")
            elif _vix_regime in ("CONFIDENCE", "EUPHORIA"):
                _idx_score += 1; _idx_reasons.append(f"VIX={_vix:.1f}(calm)")
            
            _idx_direction = None
            
            # Nifty technicals from scan data
            if scans:
                _scan_list_idx = scans if isinstance(scans, list) else [scans[k] for k in scans]
                for _sd_idx in _scan_list_idx:
                    if isinstance(_sd_idx, dict) and _sd_idx.get("symbol") == "NIFTY":
                        _n_rsi = _sd_idx.get("rsi", 50)
                        _n_macd = _sd_idx.get("macd_bull", False)
                        _n_chg = _sd_idx.get("day_change_pct", 0)
                        
                        if _n_rsi < 35:
                            _idx_score += 3; _idx_reasons.append(f"RSI={_n_rsi:.0f}(oversold)")
                            _idx_direction = "BULLISH"
                        elif _n_rsi > 72:
                            _idx_score += 3; _idx_reasons.append(f"RSI={_n_rsi:.0f}(overbought)")
                            _idx_direction = "BEARISH"
                        if _n_macd:
                            _idx_score += 1; _idx_reasons.append("MACD+")
                            if not _idx_direction: _idx_direction = "BULLISH"
                        else:
                            _idx_score += 1; _idx_reasons.append("MACD-")
                            if not _idx_direction: _idx_direction = "BEARISH"
                        if abs(_n_chg) >= 0.8:
                            _idx_score += 2; _idx_reasons.append(f"Nifty{_n_chg:+.1f}%")
                            if not _idx_direction:
                                _idx_direction = "BULLISH" if _n_chg > 0 else "BEARISH"
                        break
            
            # RBI MPC proximity
            _today_str = now_ist().strftime("%Y-%m-%d")
            _rbi_mpc_dates = FNOIntelEngine.RBI_MPC_DATES_2026
            _days_to_mpc = 999
            for _mpc_dt in _rbi_mpc_dates:
                try:
                    _mpc_d = datetime.strptime(_mpc_dt, "%Y-%m-%d").date()
                    _diff = (_mpc_d - now_ist().date()).days
                    if 0 <= _diff < _days_to_mpc:
                        _days_to_mpc = _diff
                except: pass
            if 0 <= _days_to_mpc <= 3:
                _idx_score += 3; _idx_reasons.append(f"RBI_MPC_in_{_days_to_mpc}d")
                if _vix > 22 and not _idx_direction:
                    _idx_reasons.append("VIX_high_skip_direction")
            
            # Market breadth
            if scans:
                _sl_idx = scans if isinstance(scans, list) else [scans[k] for k in scans]
                _bull_c = sum(1 for s in _sl_idx if isinstance(s, dict) and "BUY" in s.get("overall", ""))
                _bear_c = sum(1 for s in _sl_idx if isinstance(s, dict) and "SELL" in s.get("overall", ""))
                _total_c = len(_sl_idx) or 1
                _breadth = (_bull_c - _bear_c) / _total_c * 100
                if _breadth > 25:
                    _idx_score += 2; _idx_reasons.append(f"Breadth+{_breadth:.0f}%")
                    if not _idx_direction: _idx_direction = "BULLISH"
                elif _breadth < -25:
                    _idx_score += 2; _idx_reasons.append(f"Breadth{_breadth:.0f}%")
                    if not _idx_direction: _idx_direction = "BEARISH"
            
            if _idx_score >= 5 and _idx_direction:
                self._fno_queue.append({
                    "symbol": "NIFTY", "engine": "INDEX_OPTIONS",
                    "score": min(_idx_score * 10, 100),
                    "catalyst": " | ".join(_idx_reasons),
                    "direction": _idx_direction,
                    "data": {"price": _nifty_spot, "vix": _vix, "regime": _vix_regime},
                    "pod": "Index",
                })
                logger.info(f"📊 F&O BRAIN INDEX: NIFTY {_idx_direction} score={_idx_score*10} spot={_nifty_spot:.0f}")
                
                if _bnf_spot > 0:
                    self._fno_queue.append({
                        "symbol": "BANKNIFTY", "engine": "INDEX_OPTIONS",
                        "score": min(_idx_score * 10, 100),
                        "catalyst": " | ".join(_idx_reasons),
                        "direction": _idx_direction,
                        "data": {"price": _bnf_spot, "vix": _vix, "regime": _vix_regime},
                        "pod": "Index",
                    })
            elif _idx_score >= 3:
                logger.info(f"📊 F&O BRAIN INDEX: score={_idx_score*10} (need 50) | dir={_idx_direction or 'UNCLEAR'}")
        except Exception as e:
            logger.debug(f"F&O Brain index scan: {e}")
    
    def run_exit_checks(self, kite=None):
        """Run F&O exit engine — 18 rules, every 5 minutes."""
        if self.exit_engine:
            try:
                return self.exit_engine.check_all_exits(
                    fno_trader=self.trader,
                    kite=kite or KiteSession.get(),
                )
            except Exception as e:
                logger.error(f"F&O BRAIN exit check: {e}")
        return []
    
    def get_queue(self):
        return self._fno_queue
    
    def reset_daily(self):
        """Reset F&O brain state for new day."""
        self._fno_queue = []
        if self.moonshot:
            self.moonshot.active_tickets = []
            self.moonshot._scan_results_cache = []
        if self.exit_engine:
            self.exit_engine.reset_daily()
        logger.info("🧠 F&O BRAIN: Daily reset complete")


