            logger.info(f"  {_pc['icon']} {_pn}: SL {_pc['sl_atr_mult']}×ATR | T1 {_pc['t1_atr_mult']}×ATR | T2 {_pc['t2_atr_mult']}×ATR | Conf≥{_pc['confidence_min']} | {_pc['strategy']}")
