    def __init__(self, brokerage_monitor=None, tl_data=None, pipeline=None):
        self.bm = brokerage_monitor
        self.tl_data = tl_data if tl_data is not None else pd.DataFrame()
        self.pipeline = pipeline
        self.battle_plan = {"equity": [], "fno": [], "moonshot": [], "macro_plays": []}
        self._last_plan_time = None
        self._plan_version = 0
        self._sent_plans = set()
        logger.info("🧠 IntelligenceDecisionEngine initialized — 24/7 decision brain active")

    def _match_stocks_from_headline(self, title):
        """Extract stock symbols from a news headline."""
        title_lower = title.lower()
        matched = []
        for name, symbol in self.COMPANY_MAP.items():
            if symbol and name in title_lower:
                matched.append(symbol)
        # Also check F&O stock names directly
        for sym in FNO_STOCKS:
            if sym.lower() in title_lower or sym.lower().replace("_", "") in title_lower:
                if sym not in matched:
                    matched.append(sym)
        return matched

    def _score_news_hit(self, hit):
        """Score a single news hit: -100 to +100."""
        keywords = hit.get("keywords", [])
        title_lower = hit.get("title", "").lower()
        score = 0
        direction = "NEUTRAL"
        
        # Keyword scoring
        for kw in keywords:
            if kw in self.STRONG_BULL:
                score += 25
            elif kw in self.MODERATE_BULL:
                score += 12
            elif kw in self.STRONG_BEAR:
                score -= 25
            elif kw in ("stocks to buy", "top pick", "outperform", "initiates coverage", "raises target"):
                score += 18
            else:
                score += 5  # Generic keyword match
        
        # Source quality bonus
        source = hit.get("source", "").lower()
        tier1_sources = {"economic times", "moneycontrol", "livemint", "financial express", "cnbctv18"}
        if any(t in source for t in tier1_sources):
            score = int(score * 1.2)
        
        # Cap score
        score = max(-100, min(100, score))
        if score > 15:
            direction = "BULLISH"
        elif score < -15:
            direction = "BEARISH"
        
        return score, direction
    
    def _get_macro_plays(self, all_hits):
        """Detect macro themes from news and map to F&O plays."""
        macro_plays = []
        all_titles = " ".join(h.get("title", "").lower() for h in all_hits)
        
        for trigger, play in self.MACRO_FNO_MAP.items():
            if trigger in all_titles:
                macro_plays.append({
                    "trigger": trigger,
                    "sector": play["sector"],
                    "direction": play["direction"],
                    "reason": play["reason"],
                    "stocks": play["stocks"],
                    "count": all_titles.count(trigger),
                })
        
        # Sort by mention count (more mentions = stronger signal)
        macro_plays.sort(key=lambda x: x["count"], reverse=True)
        return macro_plays[:5]  # Top 5 macro themes

    def _get_dvm_score(self, symbol):
        """Get DVM score from TrendLyne data."""
        if self.tl_data.empty:
            return 50  # Default if no data
        try:
            row = self.tl_data[self.tl_data["Symbol"] == symbol]
            if row.empty:
                row = self.tl_data[self.tl_data["Symbol"].str.upper() == symbol.upper()]
            if not row.empty:
                return row.iloc[0].get("DVM Score", row.iloc[0].get("DVM", 50))
        except:
            pass
        return 50

    def _get_sector(self, symbol):
        """Get sector from TrendLyne or pod config."""
        if not self.tl_data.empty:
            try:
                row = self.tl_data[self.tl_data["Symbol"].str.upper() == symbol.upper()]
                if not row.empty:
                    return str(row.iloc[0].get("Sector", row.iloc[0].get("Industry", "")))
            except:
                pass
        return ""

    def build_battle_plan(self, all_hits):
        """
        THE CORE DECISION ENGINE.
        Takes news hits → produces ranked buy/sell lists for equity + F&O.
        Runs every cycle (30 min market, 2 hrs weekends).
        """
        equity_candidates = []
        fno_candidates = []
        
        # ── Step 1: Score each hit and map to stocks ──
        for hit in all_hits:
            score, direction = self._score_news_hit(hit)
            if abs(score) < 10:
                continue  # Skip low-signal noise
            
            stocks = self._match_stocks_from_headline(hit["title"])
            for sym in stocks:
                if sym in ("NIFTY", "BANKNIFTY"):
                    # Index-level signal → F&O only
                    fno_candidates.append({
                        "symbol": sym,
                        "score": max(abs(score), 20),
                        "direction": direction,
                        "reason": hit["title"][:100],
                        "source": hit.get("source", ""),
                        "keywords": hit.get("keywords", []),
                        "type": "INDEX",
                    })
                    continue
                
                dvm = self._get_dvm_score(sym)
                sector = self._get_sector(sym)
                pod = _get_pod_for_sector(sector)
                pod_name = [k for k, v in GRIFFIN_POD_CONFIG.items() if v == pod][0] if pod else "SERVICES"
                
                candidate = {
                    "symbol": sym,
                    "news_score": score,
                    "direction": direction,
                    "dvm": dvm,
                    "sector": sector,
                    "pod": pod_name,
                    "reason": hit["title"][:100],
                    "source": hit.get("source", ""),
                    "keywords": hit.get("keywords", []),
                    "combined_score": score + (dvm - 50),  # DVM bonus/penalty
                }
                
                # Route: F&O-eligible stocks with strong signals → F&O
                if sym in FNO_STOCKS and abs(score) >= 20:
                    fno_candidates.append({**candidate, "type": "STOCK_OPTION"})
                
                # All qualifying stocks → equity
                if direction == "BULLISH" and dvm >= 50:
                    equity_candidates.append(candidate)
        
        # ── Step 2: Deduplicate (keep highest score per symbol) ──
        equity_dedup = {}
        for c in equity_candidates:
            sym = c["symbol"]
            if sym not in equity_dedup or c["combined_score"] > equity_dedup[sym]["combined_score"]:
                equity_dedup[sym] = c
        
        fno_dedup = {}
        for c in fno_candidates:
            sym = c["symbol"]
            if sym not in fno_dedup or c["score"] > fno_dedup[sym]["score"]:
                fno_dedup[sym] = c
        
        # ── Step 2b: Add macro play stocks to equity candidates ──
        for macro in self._get_macro_plays(all_hits):
            if macro["direction"] == "BULLISH":
                for sym in macro.get("stocks", [])[:3]:
                    if sym not in equity_dedup:
                        dvm = self._get_dvm_score(sym)
                        sector = self._get_sector(sym)
                        pod = _get_pod_for_sector(sector)
                        pod_name = [k for k, v in GRIFFIN_POD_CONFIG.items() if v == pod][0] if pod else "SERVICES"
                        macro_score = 15 + (macro["count"] * 5)
                        equity_dedup[sym] = {
                            "symbol": sym, "news_score": macro_score, "direction": "BULLISH",
                            "dvm": dvm, "sector": sector, "pod": pod_name,
                            "reason": f"MACRO: {macro['trigger']} — {macro['reason']}",
                            "source": "MACRO_INTELLIGENCE", "keywords": [macro["trigger"]],
                            "combined_score": macro_score + (dvm - 50),
                        }
                        if sym in FNO_STOCKS and sym not in fno_dedup:
                            fno_dedup[sym] = {
                                "symbol": sym, "score": macro_score, "direction": "BULLISH",
                                "reason": f"MACRO: {macro['trigger']} — {macro['reason']}",
                                "source": "MACRO_INTELLIGENCE", "type": "STOCK_OPTION",
                            }

        # ── Step 3: Rank ──
        ranked_equity = sorted(equity_dedup.values(), key=lambda x: x["combined_score"], reverse=True)[:15]
        ranked_fno = sorted(fno_dedup.values(), key=lambda x: x.get("score", 0), reverse=True)[:10]
        
        # ── Step 4: Macro plays ──
        macro_plays = self._get_macro_plays(all_hits)
        
        # ── Step 5: Update battle plan ──
        self.battle_plan = {
            "equity": ranked_equity,
            "fno": ranked_fno,
            "macro_plays": macro_plays,
            "timestamp": datetime.now().isoformat(),
            "total_hits": len(all_hits),
            "version": self._plan_version + 1,
        }
        self._plan_version += 1
        self._last_plan_time = datetime.now()
        
        # ── Step 6: Log decisions ──
        if ranked_equity or ranked_fno or macro_plays:
            logger.info(f"🧠 BATTLE PLAN v{self._plan_version}: "
                       f"Equity={len(ranked_equity)} F&O={len(ranked_fno)} Macro={len(macro_plays)}")
            for c in ranked_equity[:5]:
                pod_icon = GRIFFIN_POD_CONFIG.get(c["pod"], {}).get("icon", "📈")
                logger.info(f"  {pod_icon} EQ: {c['symbol']} score={c['combined_score']} "
                           f"DVM={c['dvm']} | {c['direction']} | {c['reason'][:60]}")
            for c in ranked_fno[:3]:
                logger.info(f"  🎯 F&O: {c['symbol']} score={c.get('score',0)} "
                           f"{c['direction']} | {c.get('reason','')[:60]}")
            for m in macro_plays[:3]:
                logger.info(f"  🌍 MACRO: {m['trigger']} → {m['sector']} {m['direction']} "
                           f"| {m['reason']} | mentions={m['count']}")
        else:
            logger.info("🧠 BATTLE PLAN: No actionable signals this cycle")
        
        # ── Step 7: Save to disk for persistence across restarts ──
        try:
            plan_path = os.path.join(DATA_DIR, "battle_plan.json")
            import json
            with open(plan_path, "w") as fp:
                json.dump(self.battle_plan, fp, default=str, indent=2)
        except Exception as _save_err:
            logger.debug(f"Battle plan save: {_save_err}")
        
        return self.battle_plan

    def get_telegram_plan(self):
        """Format battle plan for Telegram notification."""
        bp = self.battle_plan
        if not bp.get("equity") and not bp.get("fno") and not bp.get("macro_plays"):
            return None
        
        is_td = KiteSession.is_trading_day()
        header = "📋 *NEXT-DAY BATTLE PLAN*" if not is_td else "📋 *LIVE BATTLE PLAN UPDATE*"
        
        lines = [header, f"_v{bp.get('version',0)} | {bp.get('total_hits',0)} news analyzed_", ""]
        
        # Macro themes
        if bp.get("macro_plays"):
            lines.append("🌍 *MACRO THEMES:*")
            for m in bp["macro_plays"][:3]:
                arrow = "🟢" if m["direction"] == "BULLISH" else "🔴" if m["direction"] == "BEARISH" else "⚪"
                lines.append(f"  {arrow} {m['trigger'].upper()} → {m['sector']} ({m['reason']})")
            lines.append("")
        
        # Equity picks
        if bp.get("equity"):
            lines.append("📈 *EQUITY BUY LIST:*")
            for c in bp["equity"][:7]:
                pod_cfg = GRIFFIN_POD_CONFIG.get(c["pod"], {})
                icon = pod_cfg.get("icon", "📈")
                lines.append(f"  {icon} `{c['symbol']}` [{c['pod']}] "
                           f"Score:{c['combined_score']} DVM:{c['dvm']}")
            lines.append("")
        
        # F&O picks
        if bp.get("fno"):
            lines.append("🎯 *F&O SIGNALS:*")
            for c in bp["fno"][:5]:
                arrow = "📗 CE" if c.get("direction") == "BULLISH" else "📕 PE"
                lines.append(f"  {arrow} `{c['symbol']}` Score:{c.get('score',0)} | {c.get('reason','')[:50]}")
            lines.append("")
        
        if not is_td:
            lines.append("⏰ _Execution queued for next market open_")
        
        return "\n".join(lines)

    def feed_to_pipeline(self, pipeline):
        """Push battle plan candidates into the AutonomousPipeline queues."""
        if not pipeline or not self.battle_plan.get("equity"):
            return
        
        # Feed equity candidates as proposals
        for c in self.battle_plan["equity"][:10]:
            pipeline.equity_queue.append({
                "symbol": c["symbol"],
                "engine": "EQUITY",
                "confidence": c["combined_score"],
                "dvm": c["dvm"],
                "pod": c["pod"],
                "ltp": 0,  # Will be filled at market open
                "atr": 0,
                "sl_atr_mult": GRIFFIN_POD_CONFIG.get(c["pod"], {}).get("sl_atr_mult", 2.0),
                "t2_atr_mult": GRIFFIN_POD_CONFIG.get(c["pod"], {}).get("t2_atr_mult", 12.0),
                "data": c,
                "source": "INTELLIGENCE_ENGINE",
            })
        
        # Feed F&O candidates
        for c in self.battle_plan.get("fno", [])[:5]:
            pipeline.fno_queue.append({
                "symbol": c["symbol"],
                "engine": "SAFE_FNO",
                "score": c.get("score", 0),
                "catalyst": "NEWS_SIGNAL",
                "direction": c.get("direction", "BULLISH"),
                "data": c,
                "source": "INTELLIGENCE_ENGINE",
            })
        
        logger.info(f"🧠→⚡ Fed {len(self.battle_plan['equity'][:10])} equity + "
                    f"{len(self.battle_plan.get('fno', [])[:5])} F&O candidates to pipeline")


